            </div>
            <div class="text-caption opacity-8">
              {{ t('import_configuration_description') }}
            </div>
          </div>
        </div>

        <!-- Form -->
        <q-form ref="formRef" @submit.prevent="handleSubmit" class="config-form q-pt-sm">
          
          <!-- Section: Basic Settings -->
          <div class="form-section">
            <div class="section-label q-mb-sm">
              <q-icon name="info_outline" size="18px" class="q-mr-xs" />
              {{ t('basic_information') }}
              <q-space />
              <div v-if="mode === 'edit'" class="section-toggle">
                <span class="section-toggle-label">{{ form.is_active ? t('active') : t('inactive') }}</span>
                <f-toggle
                  v-model="form.is_active"
                  size="sm"
                />
              </div>
            </div>

            <div class="row q-col-gutter-sm">
              <!-- Config type is now always 'import' - export configs are managed in Export Settings -->
              <div class="col-12">
                <div class="form-field">
                  <label class="field-label required">{{ t('configuration_name') }}</label>
                  <q-input
                    v-model="form.name"
                    outlined
                    dense
                    hide-bottom-space
                    class="modern-input"
                    :placeholder="t('configuration_name_placeholder')"
                    :rules="[val => !!val || t('field_required')]"
                    lazy-rules
                  />
                </div>
              </div>

              <div class="col-12 col-md-6">
                <div class="form-field">
                  <label class="field-label">{{ t('sub_organization') }}</label>
                  <q-select
                    v-model="form.sub_org_id"
                    :options="subOrgOptions"
                    outlined
                    dense
                    hide-bottom-space
                    emit-value
                    map-options
                    class="modern-input"
                    popup-content-class="dropdown-fit"
                    :option-label="opt => opt.label"
                    :option-value="opt => opt.value"
                  >
                    <template v-slot:option="scope">
                      <q-item v-bind="scope.itemProps">
                        <q-item-section>
                          <q-item-label>{{ scope.opt.label }}</q-item-label>
                          <q-tooltip>{{ scope.opt.label }}</q-tooltip>
                        </q-item-section>
                      </q-item>
                    </template>
                  </q-select>
                </div>
              </div>

              <div class="col-12 col-md-6">
                <div class="form-field">
                  <label class="field-label">{{ t('document_type') }}</label>
                  <q-select
                    v-model="form.doc_type_key"
                    :options="docTypeOptions"
                    outlined
                    dense
                    hide-bottom-space
                    emit-value
                    map-options
                    class="modern-input"
                    :option-label="opt => opt.label"
                    :option-value="opt => opt.value"
                  />
                </div>
              </div>
            </div>
          </div>

          <q-separator class="q-my-sm opacity-5" />

          <!-- Section: Import Path Settings -->
          <div class="form-section">
            <div class="section-label q-mb-sm">
              <q-icon name="download" size="18px" class="q-mr-xs" />
              {{ t('import_settings') }}
            </div>

            <!-- Import Logic -->
            <div class="row q-col-gutter-sm">
              <div class="col-12">
                <div class="form-field">
                  <label class="field-label required">{{ t('watch_folder_path') }}</label>
                  <q-input
                    v-model="form.import_path"
                    outlined
                    dense
                    hide-bottom-space
                    class="modern-input font-mono"
                    placeholder="C:\WatchDog\import"
                    :rules="[val => !!val || t('field_required')]"
                    lazy-rules
                  >
                    <template v-slot:prepend><q-icon name="folder" size="20px" color="grey-6" /></template>
                  </q-input>
                </div>
              </div>
              <div class="col-12">
                <div class="form-field">
                  <label class="field-label">{{ t('success_folder_path') }}</label>
                  <q-input
                    v-model="form.success_path"
                    outlined
                    dense
                    hide-bottom-space
                    class="modern-input font-mono"
                    placeholder="C:\WatchDog\success"
                  >
                    <template v-slot:prepend><q-icon name="folder_shared" size="20px" color="grey-6" /></template>
                  </q-input>
                </div>
              </div>
            </div>
          </div>

          <q-separator class="q-my-sm opacity-5" />

          <!-- Section: BOD Mapping -->
          <div class="form-section">
            <div class="section-label q-mb-sm">
              <q-icon name="swap_horiz" size="18px" class="q-mr-xs" />
              {{ t('bod_mapping') || 'BOD Mapping' }}
            </div>

            <div class="bod-mapping-section">
              <q-btn
                flat
                dense
                no-caps
                icon="add"
                :label="t('add_entry') || 'Add Entry'"
                color="primary"
                size="sm"
                class="q-mb-sm"
                @click="addBodMappingRow"
              />

              <div v-if="bodMappingRows.length > 0" class="bod-mapping-table">
                <div class="bod-mapping-header">
                  <span class="bod-col-key">{{ t('key') || 'Key' }}</span>
                  <span class="bod-col-value">{{ t('value') || 'Value' }}</span>
                  <span class="bod-col-actions"></span>
                </div>
