        />
        <q-btn
          unelevated
          :label="t('save_configuration')"
          color="primary"
          no-caps
          :loading="saving"
          :disable="hasDuplicateError"
          @click="handleSubmit"
        />
      </q-card-actions>
    </q-card>
  </q-dialog>
</template>

<script setup lang="ts">
import { ref, computed, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import type {
  WatchdogConfiguration,
  WatchdogConfigurationInput,
  DropdownOption,
  ConfigModalMode,
  ConfigType,
} from '../types/watchdog.types';

const t = useTranslate().t;

// Props
interface Props {
  modelValue: boolean;
  mode: ConfigModalMode;
  configuration?: WatchdogConfiguration | null;
  docTypes: Array<{ key: string; title: string }>;
  subOrgs?: DropdownOption[];
  existingConfigurations?: WatchdogConfiguration[];
}

const props = withDefaults(defineProps<Props>(), {
  configuration: null,
  subOrgs: () => [],
  existingConfigurations: () => [],
});

// Emits
const emit = defineEmits<{
  (e: 'update:modelValue', value: boolean): void;
  (e: 'save', input: WatchdogConfigurationInput): void;
}>();

// Refs
const formRef = ref<any>(null);
const saving = ref(false);

// BOD Mapping rows (internal editable list)
const bodMappingRows = ref<Array<{ key: string; value: string }>>([]);

// Form state - import configurations only (export configs are managed in Export Settings)
const form = ref<{
  name: string;
  config_type: ConfigType;
  sub_org_id: string | null;
  doc_type_key: string | null;
  import_path: string;
  success_path: string;
  is_default: boolean;
  is_active: boolean;
}>({
  name: '',
  config_type: 'import',
  sub_org_id: null,
  doc_type_key: null,
  import_path: '',
  success_path: '',
  is_default: false,
  is_active: true,
});


// Computed - Modal is now import-only
const modalTitle = computed(() => {
  const typeLabel = t.value('import_type');
  switch (props.mode) {
    case 'create':
      return t.value('new_configuration_title', { type: typeLabel });
    case 'edit':
      return t.value('edit_configuration_title', { type: typeLabel });
    case 'copy':
      return t.value('copy_configuration_title', { type: typeLabel });
    default:
      return t.value('configuration_title', { type: typeLabel });
  }
});

const subOrgOptions = computed<DropdownOption[]>(() => {
  const options: DropdownOption[] = [
    { label: t.value('all_sub_organizations'), value: null },
  ];
  if (props.subOrgs && props.subOrgs.length > 0) {
    options.push(...props.subOrgs);
  }
  return options;
});

const docTypeOptions = computed<DropdownOption[]>(() => {
  const options: DropdownOption[] = [
    { label: t.value('all_document_types'), value: null },
  ];
  props.docTypes.forEach((dt) => {
    options.push({ label: dt.title, value: dt.key });
  });
  return options;
});

// Check for conflicting configuration (duplicate config_type + sub_org + doc_type combination)
const conflictingConfig = computed((): WatchdogConfiguration | null => {
  // In edit mode, we exclude the current configuration from conflict check.
  // In copy or create mode, we check against all existing configurations.
  const excludeId = props.mode === 'edit' ? props.configuration?.id : undefined;

  return (
    props.existingConfigurations.find(
      (c) =>
        c.id !== excludeId &&
        (c.sub_org_id || null) === (form.value.sub_org_id || null) &&
        (c.doc_type_key || null) === (form.value.doc_type_key || null)  &&
        (c.config_type || null) === (form.value.config_type || null),
    ) || null
  );
});

// Flag indicating if there's a duplicate error
const hasDuplicateError = computed(() => !!conflictingConfig.value);

// Watch for configuration changes to populate form (import configs only)
watch(
  () => props.modelValue,
  (isOpen) => {
    if (isOpen) {
      if (props.configuration && (props.mode === 'edit' || props.mode === 'copy')) {
        // Populate form with existing import configuration
        form.value = {
          name: props.mode === 'copy'
            ? `${props.configuration.name} (Copy)`
            : props.configuration.name,
          config_type: 'import', // Always import in this modal
          sub_org_id: props.configuration.sub_org_id,
          doc_type_key: props.configuration.doc_type_key,
          import_path: props.configuration.import_path || '',
          success_path: props.configuration.success_path || '',
          is_default: props.mode === 'copy' ? false : props.configuration.is_default,
          is_active: props.configuration.is_active,
        };
        bodMappingRows.value = bodMappingToRows(props.configuration.bod_mapping);
      } else {
        // Reset form for new configuration
        resetForm();
      }
    }
  },
  { immediate: true }
);

// BOD Mapping methods
const addBodMappingRow = () => {
  bodMappingRows.value.push({ key: '', value: '' });
};

const removeBodMappingRow = (index: number) => {
  bodMappingRows.value.splice(index, 1);
};

/** Convert bod_mapping Record to editable rows */
const bodMappingToRows = (mapping?: Record<string, string>): Array<{ key: string; value: string }> => {
  if (!mapping) return [];
  return Object.entries(mapping).map(([key, value]) => ({ key, value }));
};

/** Convert editable rows back to Record for API */
const rowsToBodMapping = (rows: Array<{ key: string; value: string }>): Record<string, string> | undefined => {
  const filtered = rows.filter(r => r.key.trim() !== '');
  if (filtered.length === 0) return undefined;
  const result: Record<string, string> = {};
  for (const row of filtered) {
    result[row.key] = row.value;
  }
  return result;
};

// Methods
const resetForm = () => {
  form.value = {
    name: '',
    config_type: 'import',
    sub_org_id: null,
    doc_type_key: null,
    import_path: '',
    success_path: '',
    is_default: false,
    is_active: true,
  };
  bodMappingRows.value = [];
};

const closeModal = () => {
  emit('update:modelValue', false);
  resetForm();
};

const handleSubmit = async () => {
  const isValid = await formRef.value?.validate();
  if (!isValid) return;

  saving.value = true;
  try {
    // Import configuration only - export configs are managed in Export Settings
    const input: WatchdogConfigurationInput = {
      name: form.value.name,
      config_type: 'import',
      sub_org_id: form.value.sub_org_id,
      doc_type_key: form.value.doc_type_key,
      import_path: form.value.import_path,
      success_path: form.value.success_path || null,
      export_path: null,  // Not used for import configs
      xslt_template_id: null,  // Not used for import configs
      is_default: form.value.is_default,
      is_active: form.value.is_active,
      bod_mapping: rowsToBodMapping(bodMappingRows.value),
    };

    emit('save', input);
  } finally {
    saving.value = false;
  }
};
</script>

