<template>
  <q-dialog
    :model-value="show"
    @update:model-value="$emit('update:show', $event)"
    persistent
    class="bulk-copy-modal"
  >
    <q-card class="modal-card column no-wrap">
      <!-- Header -->
      <q-card-section class="modal-header row items-center no-wrap">
        <div class="text-h6">{{ t('bulk_copy_to_sub_orgs') }}</div>
        <q-space />
        <q-btn
          icon="close"
          flat
          round
          dense
          @click="closeModal"
          :disable="processing"
        />
      </q-card-section>

      <!-- Stepper Content -->
      <q-card-section class="modal-content col">
        <q-stepper
          v-model="currentStep"
          color="primary"
          animated
          flat
          class="bulk-copy-stepper"
        >
          <!-- Step 1: Select Target Sub-Orgs -->
          <q-step
            :name="1"
            :title="t('select_target_sub_orgs')"
            icon="business"
            :done="currentStep > 1"
          >
            <div class="step-content">
              <div class="field-label">{{ t('select_target_sub_orgs') }}</div>
              <q-select
                v-model="selectedSubOrgIds"
                :options="availableSubOrgs"
                multiple
                outlined
                dense
                use-chips
                emit-value
                map-options
                :option-label="opt => opt.label"
                :option-value="opt => opt.value"
                :option-disable="opt => opt.hasExisting"
                :placeholder="t('select_sub_orgs_placeholder')"
                class="q-mb-md"
                popup-content-class="dropdown-fit"
              >
                <template v-slot:option="scope">
                  <q-item
                    v-bind="scope.itemProps"
                    :class="{ 'option-disabled': scope.opt.hasExisting }"
                  >
                    <q-item-section>
                      <q-item-label>{{ scope.opt.label }}</q-item-label>
                      <q-item-label v-if="scope.opt.hasExisting" caption class="text-negative">
                        {{ t('config_already_exists_for_suborg') }}
                      </q-item-label>
                      <q-tooltip>{{ scope.opt.label }}</q-tooltip>
                    </q-item-section>
                    <q-item-section side v-if="scope.opt.hasExisting">
                      <q-badge color="negative" :label="t('exists')" />
                    </q-item-section>
                  </q-item>
                </template>
              </q-select>

              <div v-if="selectedSubOrgIds.length > 0" class="selection-summary">
                {{ t('sub_orgs_selected', { count: selectedSubOrgIds.length }) }}
              </div>

              <div v-if="subOrgsWithExistingConfigs.length > 0" class="warning-banner q-mt-md">
                <q-icon name="warning" color="warning" size="20px" class="q-mr-sm" />
                <span>{{ t('existing_configs_warning', { count: subOrgsWithExistingConfigs.length }) }}</span>
              </div>
            </div>

            <q-stepper-navigation>
              <q-btn
                @click="currentStep = 2"
                color="primary"
                :label="t('next')"
                :disable="selectedSubOrgIds.length === 0"
                unelevated
                no-caps
              />
            </q-stepper-navigation>
          </q-step>

          <!-- Step 2: Preview -->
          <q-step
            :name="2"
            :title="t('preview_bulk_copy')"
            icon="preview"
            :done="currentStep > 2"
          >
            <div class="step-content">
              <!-- Warning Banner -->
              <div class="info-banner q-mb-md">
                <q-icon name="info" color="info" size="20px" class="q-mr-sm" />
                <span>{{ t('bulk_copy_path_warning') }}</span>
              </div>

              <!-- Preview Table -->
              <DocBitsTable
                :rows="previewRows"
                :columns="previewColumns"
                row-key="id"
                dense
                class="preview-table"
                :features="{ sorting: false, pagination: false }"
              >
                <template #body-cell-newConfigName="{ row }">
                  <span class="config-name-preview">{{ row.newConfigName }}</span>
                </template>
              </DocBitsTable>

              <div class="summary-text q-mt-md">
                {{ t('will_create_configs', { count: previewRows.length }) }}
              </div>
            </div>

            <q-stepper-navigation>
              <q-btn
                @click="executeBuilkCopy"
                color="primary"
                :label="t('create_configurations')"
                :loading="processing"
                unelevated
                no-caps
              />
              <q-btn
                flat
                @click="currentStep = 1"
                :label="t('back')"
                class="q-ml-sm"
                no-caps
                :disable="processing"
              />
            </q-stepper-navigation>
          </q-step>

          <!-- Step 3: Result -->
          <q-step
            :name="3"
            :title="t('bulk_copy_result')"
            icon="check_circle"
          >
            <div class="step-content">
              <!-- Progress (while processing) -->
              <div v-if="processing" class="progress-section q-mb-lg">
                <div class="progress-label q-mb-sm">{{ t('creating_configurations') }}</div>
                <q-linear-progress
                  :value="progressValue"
                  color="primary"
                  size="8px"
                  class="q-mb-sm"
                />
                <div class="progress-count text-grey-6">
                  {{ processedCount }} / {{ totalOperations }}
                </div>
              </div>

              <!-- Results (after processing) -->
              <div v-else>
                <!-- Summary -->
                <div
                  class="result-summary q-mb-md"
                  :class="{ 'has-failures': failureCount > 0 }"
                >
                  <q-icon
                    :name="failureCount === 0 ? 'check_circle' : 'warning'"
                    :color="failureCount === 0 ? 'positive' : 'warning'"
                    size="24px"
                    class="q-mr-sm"
                  />
                  <span>{{ t('bulk_copy_complete', { success: successCount, total: totalOperations }) }}</span>
                </div>

                <!-- Results Table -->
                <DocBitsTable
                  :rows="results"
                  :columns="resultsColumns"
                  row-key="id"
                  dense
                  class="results-table"
                  :features="{ sorting: false, pagination: false }"
                >
                  <template #body-cell-status="{ row }">
                    <q-badge
                      :color="row.success ? 'positive' : 'negative'"
                      :label="row.success ? t('success') : t('failed')"
                    />
                  </template>
                  <template #body-cell-error="{ row }">
                    <span v-if="row.error" class="text-negative">{{ row.error }}</span>
                    <span v-else class="text-grey-5">-</span>
                  </template>
                </DocBitsTable>
              </div>
            </div>

            <q-stepper-navigation v-if="!processing">
              <q-btn
                @click="closeAndComplete"
                color="primary"
                :label="t('close')"
                unelevated
                no-caps
              />
            </q-stepper-navigation>
          </q-step>
        </q-stepper>
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script setup lang="ts">
import { ref, computed, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { useWatchdogStore } from '../store/watchdog.store';
import { UserSubOrg } from 'src/utils/organization/sub_organization';
import type { WatchdogConfiguration, DropdownOption } from '../types/watchdog.types';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';

const t = useTranslate().t;
const store = useWatchdogStore();

// Props
interface Props {
  show: boolean;
  sourceConfigs: WatchdogConfiguration[];
}

const props = withDefaults(defineProps<Props>(), {
  sourceConfigs: () => [],
});

// Emits
const emit = defineEmits<{
  (e: 'update:show', value: boolean): void;
  (e: 'completed'): void;
}>();

// State
const currentStep = ref(1);
const selectedSubOrgIds = ref<string[]>([]);
const processing = ref(false);
const processedCount = ref(0);
const results = ref<Array<{
  id: string;
  configName: string;
  subOrgName: string;
  success: boolean;
  error?: string;
}>>([]);

// Sub-org options
const subOrgOptions = ref<Array<DropdownOption & { hasExisting?: boolean }>>([]);

// Load sub-orgs when modal opens
watch(() => props.show, async (isOpen) => {
  if (isOpen) {
    resetState();
    await loadSubOrgs();
  }
}, { immediate: true });

// Computed
const availableSubOrgs = computed(() => {
  // Filter out sub-orgs that are already targeted by source configs
  const sourceSubOrgIds = new Set(
    props.sourceConfigs
      .filter(c => c.sub_org_id)
      .map(c => c.sub_org_id)
  );
  return subOrgOptions.value.filter(opt => opt.value && !sourceSubOrgIds.has(opt.value));
});

const subOrgsWithExistingConfigs = computed(() => {
  // Find selected sub-orgs that already have configs with same doc_type_key
  const selectedSet = new Set(selectedSubOrgIds.value);
  return subOrgOptions.value.filter(
    opt => selectedSet.has(opt.value as string) && opt.hasExisting
  );
});

const previewRows = computed(() => {
  const rows: Array<{
    id: string;
    sourceConfigName: string;
    targetSubOrg: string;
    newConfigName: string;
  }> = [];

  const selectedSubOrgs = subOrgOptions.value.filter(
    opt => selectedSubOrgIds.value.includes(opt.value as string)
  );

  for (const config of props.sourceConfigs) {
    for (const subOrg of selectedSubOrgs) {
      rows.push({
        id: `${config.id}-${subOrg.value}`,
        sourceConfigName: config.name,
        targetSubOrg: subOrg.label,
        newConfigName: `${config.name} - ${subOrg.label}`,
      });
    }
  }

  return rows;
});

const previewColumns = computed(() => [
  {
    name: 'sourceConfigName',
    label: t.value('source_config'),
    field: 'sourceConfigName',
    align: 'left' as const,
    sortable: true,
  },
  {
    name: 'targetSubOrg',
    label: t.value('target_sub_org'),
    field: 'targetSubOrg',
    align: 'left' as const,
    sortable: true,
  },
  {
    name: 'newConfigName',
    label: t.value('new_config_name'),
    field: 'newConfigName',
    align: 'left' as const,
    sortable: true,
  },
]);

const resultsColumns = computed(() => [
  {
    name: 'configName',
    label: t.value('new_config_name'),
    field: 'configName',
    align: 'left' as const,
    sortable: true,
  },
  {
    name: 'subOrgName',
    label: t.value('target_sub_org'),
    field: 'subOrgName',
    align: 'left' as const,
    sortable: true,
  },
  {
    name: 'status',
    label: t.value('status'),
    field: 'success',
    align: 'center' as const,
  },
  {
    name: 'error',
    label: t.value('error'),
    field: 'error',
    align: 'left' as const,
  },
]);

const totalOperations = computed(() => previewRows.value.length);
const progressValue = computed(() => totalOperations.value > 0 ? processedCount.value / totalOperations.value : 0);
const successCount = computed(() => results.value.filter(r => r.success).length);
const failureCount = computed(() => results.value.filter(r => !r.success).length);

// Methods
const loadSubOrgs = async () => {
  const subOrgs = UserSubOrg.getSubOrgs();
  const existingDocTypeKeys = new Set(
    store.configurations.map(c => `${c.sub_org_id || ''}-${c.doc_type_key || ''}`)
  );

  subOrgOptions.value = subOrgs.map((subOrg: { id: string; name: string }) => {
    // Check if any source config's doc_type_key already exists for this sub-org
    const hasExisting = props.sourceConfigs.some(config =>
      existingDocTypeKeys.has(`${subOrg.id}-${config.doc_type_key || ''}`)
    );
    return {
      label: subOrg.name,
      value: subOrg.id,
      hasExisting,
    };
  });
};

const resetState = () => {
  currentStep.value = 1;
  selectedSubOrgIds.value = [];
  processing.value = false;
  processedCount.value = 0;
  results.value = [];
};

const closeModal = () => {
  if (!processing.value) {
    emit('update:show', false);
    resetState();
  }
};

const closeAndComplete = () => {
  emit('update:show', false);
  emit('completed');
  resetState();
};

const executeBuilkCopy = async () => {
  processing.value = true;
  processedCount.value = 0;
  results.value = [];
  currentStep.value = 3;

  const selectedSubOrgs = subOrgOptions.value.filter(
    opt => selectedSubOrgIds.value.includes(opt.value as string)
  );

  for (const config of props.sourceConfigs) {
    for (const subOrg of selectedSubOrgs) {
      const newConfigName = `${config.name} - ${subOrg.label}`;

      try {
        // Call store to create configuration for this sub-org
        await store.createConfiguration({
          name: newConfigName,
          config_type: config.config_type,
          sub_org_id: subOrg.value as string,
          doc_type_key: config.doc_type_key,
          import_path: config.import_path,
          success_path: config.success_path,
          export_path: config.export_path,
          xslt_template_id: config.xslt_template_id,
          export_type: config.export_type,
          export_config_id: config.export_config_id,
          is_default: false,
          is_active: true,
        });

        results.value.push({
          id: `${config.id}-${subOrg.value}`,
          configName: newConfigName,
          subOrgName: subOrg.label,
          success: true,
        });
      } catch (err) {
        results.value.push({
          id: `${config.id}-${subOrg.value}`,
          configName: newConfigName,
          subOrgName: subOrg.label,
          success: false,
          error: err instanceof Error ? err.message : t.value('bulk_copy_failed'),
        });
      }

      processedCount.value++;
    }
  }

  processing.value = false;
};
</script>

