import { defineStore } from 'pinia';
import { watchdogApiService } from 'src/services';
import type {
  WatchdogConfiguration,
  WatchdogConfigurationInput,
  XsltTemplate,
  XsltTemplateInput,
  WatchdogStatus,
  WatchdogTab,
  DropdownOption,
  WatchdogExportSchema,
  ImportValidationResult,
  ImportConflict,
  ImportResult,
  V2ConfigSchema,
  V2ImportValidationResult,
  WatchdogExportType,
  XsltValidationResponse,
  XsltDocType,
} from '../types/watchdog.types';

// ============================================
// STORE STATE INTERFACE
// ============================================

export interface WatchdogState {
  // Loading states
  loading: boolean;
  configurationsLoading: boolean;
  templatesLoading: boolean;
  statusLoading: boolean;
  validationLoading: boolean;

  // Data
  configurations: WatchdogConfiguration[];
  xsltTemplates: XsltTemplate[];
  status: WatchdogStatus | null;
  xsltDocTypes: XsltDocType[];

  // UI state
  activeTab: WatchdogTab;
  targetXsltId: string | null;
  targetConfigId: string | null;

  // Error handling
  error: string | null;
}

// ============================================
// PINIA STORE DEFINITION
// ============================================

export const useWatchdogStore = defineStore('watchdog', {
  state: (): WatchdogState => ({
    // Loading states
    loading: false,
    configurationsLoading: false,
    templatesLoading: false,
    statusLoading: false,
    validationLoading: false,

    // Data
    configurations: [],
    xsltTemplates: [],
    status: null,
    xsltDocTypes: [],

    // UI state
    activeTab: 'general',
    targetXsltId: null,
    targetConfigId: null,

    // Error handling
    error: null,
  }),

  getters: {
    /**
     * Get configurations sorted by name, with default config first
     */
    sortedConfigurations: (state): WatchdogConfiguration[] => {
      return [...state.configurations].sort((a, b) => {
        // Default config always comes first
        if (a.is_default && !b.is_default) return -1;
        if (!a.is_default && b.is_default) return 1;
        // Then sort alphabetically by name
        return a.name.localeCompare(b.name);
      });
    },

    /**
     * Get only active configurations
     */
    activeConfigurations: (state): WatchdogConfiguration[] => {
      return state.configurations.filter((c) => c.is_active);
    },

    /**
     * Get the default configuration (there should be exactly one)
     */
    defaultConfiguration: (state): WatchdogConfiguration | undefined => {
      return state.configurations.find((c) => c.is_default);
    },

    /**
     * Get XSLT templates as dropdown options
     */
    templateOptions: (state): DropdownOption[] => {
      const options: DropdownOption[] = [
        { label: 'No XSLT Template', value: null },
      ];
      state.xsltTemplates.forEach((t) => {
        options.push({ label: t.name, value: t.id });
      });
      return options;
    },

    /**
     * Get templates sorted by name
     */
    sortedTemplates: (state): XsltTemplate[] => {
      return [...state.xsltTemplates].sort((a, b) =>
        a.name.localeCompare(b.name),
      );
    },

    /**
     * Check if WatchDog service is online
     */
    isOnline: (state): boolean => {
      return state.status?.online ?? false;
    },

    /**
     * Check if a configuration with given sub_org_id and doc_type_key already exists.
     * Used to prevent duplicate configurations before API calls.
     * @param subOrgId - The sub-organization ID (null for "all sub-orgs")
     * @param docTypeKey - The document type key (null for "all document types")
     * @param excludeId - Optional ID to exclude (for edit mode - exclude current config from check)
     * @returns The conflicting configuration if found, null otherwise
     */
    hasConflictingConfiguration:
      (state) =>
      (
        subOrgId: string | null,
        docTypeKey: string | null,
        excludeId?: string,
      ): WatchdogConfiguration | null => {
        return (
          state.configurations.find(
            (c) =>
              c.id !== excludeId &&
              c.sub_org_id === subOrgId &&
              c.doc_type_key === docTypeKey,
          ) || null
        );
      },
  },

  actions: {
    // ============================================
    // CONFIGURATION ACTIONS
    // ============================================

    /**
     * Load all configurations
     */
    async loadConfigurations() {
      this.configurationsLoading = true;
      this.error = null;
      try {
        this.configurations = await watchdogApiService.getConfigurations();
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to load configurations';
      } finally {
        this.configurationsLoading = false;
      }
    },

    /**
     * Create a new configuration
     */
    async createConfiguration(
      input: WatchdogConfigurationInput,
    ): Promise<WatchdogConfiguration> {
      this.loading = true;
      this.error = null;
      try {
        const newConfig = await watchdogApiService.createConfiguration(input);

        // If this is set as default, unset others in local state
        if (newConfig.is_default) {
          this.configurations.forEach((c) => {
            c.is_default = false;
          });
        }

        this.configurations.push(newConfig);
        return newConfig;
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to create configuration';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    /**
     * Update an existing configuration
     */
    async updateConfiguration(
      id: string,
      input: Partial<WatchdogConfigurationInput>,
    ): Promise<WatchdogConfiguration> {
      this.loading = true;
      this.error = null;
      try {
        const updated = await watchdogApiService.updateConfiguration(id, input);

        const index = this.configurations.findIndex((c) => c.id === id);
        if (index === -1) {
          throw new Error('Configuration not found');
        }

        // If setting this as default, unset others in local state
        if (updated.is_default) {
          this.configurations.forEach((c) => {
            c.is_default = false;
          });
        }

        this.configurations[index] = updated;
        return updated;
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to update configuration';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    /**
     * Delete a configuration
     */
    async deleteConfiguration(id: string): Promise<void> {
      this.loading = true;
      this.error = null;
      try {
        console.log('Attempting to delete configuration:',  this.configurations);
        const config = this.configurations.find((c) => c.id === id);
        console.log('Attempting to delete configuration:', { id, config });
        if (!config) {
          throw new Error('Configuration not found');
        }
        if (config.is_default) {
          throw new Error('Cannot delete the default configuration');
        }

        await watchdogApiService.deleteConfiguration(id);

        this.configurations = this.configurations.filter((c) => c.id !== id);
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to delete configuration';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    /**
     * Set a configuration as the default
     */
    async setDefaultConfiguration(id: string): Promise<void> {
      this.loading = true;
      this.error = null;
      try {
        await watchdogApiService.updateConfiguration(id, { is_default: true });

        // Unset all others, set this one
        this.configurations.forEach((c) => {
          c.is_default = c.id === id;
          if (c.id === id) {
            c.updated_at = new Date().toISOString();
          }
        });
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to set default configuration';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    /**
     * Toggle a configuration's active status
     */
    async toggleConfigurationActive(id: string): Promise<void> {
      const config = this.configurations.find((c) => c.id === id);
      if (!config) {
        throw new Error('Configuration not found');
      }
      if (config.is_default && config.is_active) {
        throw new Error('Cannot deactivate the default configuration');
      }

      await this.updateConfiguration(id, { is_active: !config.is_active });
    },

    /**
     * Copy a configuration with a new name
     * Returns the new config with "(Copy)" suffix
     */
    async copyConfiguration(id: string): Promise<WatchdogConfiguration> {
      const source = this.configurations.find((c) => c.id === id);
      if (!source) {
        throw new Error('Source configuration not found');
      }

      const copyInput: WatchdogConfigurationInput = {
        name: `${source.name} (Copy)`,
        config_type: source.config_type,
        sub_org_id: source.sub_org_id,
        doc_type_key: source.doc_type_key,
        import_path: source.import_path,
        success_path: source.success_path,
        export_path: source.export_path,
        xslt_template_id: source.xslt_template_id,
        export_type: source.export_type,
        export_config_id: source.export_config_id,
        // REST API fields
        rest_api_url: source.rest_api_url,
        method: source.method,
        username: source.username,
        password: source.password,
        body_type: source.body_type,
        rest_api_mapping: source.rest_api_mapping,
        // GLS840MI fields
        endpoint_name: source.endpoint_name,
        // Webhook fields
        webhook_url: source.webhook_url,
        // BOD mapping
        bod_mapping: source.bod_mapping ? { ...source.bod_mapping } : undefined,
        is_default: false, // Copy is never default
        is_active: true,
      };

      return this.createConfiguration(copyInput);
    },

    /**
     * Bulk copy a configuration to multiple sub-organizations
     * Creates one copy per sub-org with paths adjusted
     */
    async bulkCopyConfiguration(
      id: string,
      subOrgIds: string[],
    ): Promise<WatchdogConfiguration[]> {
      const source = this.configurations.find((c) => c.id === id);
      if (!source) {
        throw new Error('Source configuration not found');
      }

      this.loading = true;
      this.error = null;
      try {
        const newConfigs: WatchdogConfiguration[] = [];

        for (const subOrgId of subOrgIds) {
          const copyInput: WatchdogConfigurationInput = {
            name: `${source.name} - SubOrg`,
            config_type: source.config_type,
            sub_org_id: subOrgId,
            doc_type_key: source.doc_type_key,
            import_path: source.import_path,
            success_path: source.success_path,
            export_path: source.export_path,
            xslt_template_id: source.xslt_template_id,
            export_type: source.export_type,
            export_config_id: source.export_config_id,
            // REST API fields
            rest_api_url: source.rest_api_url,
            method: source.method,
            username: source.username,
            password: source.password,
            body_type: source.body_type,
            rest_api_mapping: source.rest_api_mapping,
            // GLS840MI fields
            endpoint_name: source.endpoint_name,
            // Webhook fields
            webhook_url: source.webhook_url,
            // BOD mapping
            bod_mapping: source.bod_mapping ? { ...source.bod_mapping } : undefined,
            is_default: false,
            is_active: true,
          };

          // Temporarily disable loading state for individual creates
          this.loading = false;
          const newConfig = await this.createConfiguration(copyInput);
          newConfigs.push(newConfig);
        }

        return newConfigs;
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to bulk copy configuration';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    // ============================================
    // XSLT TEMPLATE ACTIONS
    // ============================================

    /**
     * Load all XSLT templates
     */
    async loadXsltTemplates() {
      this.templatesLoading = true;
      this.error = null;
      try {
        this.xsltTemplates = await watchdogApiService.getTemplates();
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to load XSLT templates';
      } finally {
        this.templatesLoading = false;
      }
    },

    /**
     * Load a single XSLT template with full content
     * The list endpoint may not return content to save bandwidth,
     * so this fetches the full template when editing.
     */
    async loadXsltTemplateContent(id: string): Promise<XsltTemplate> {
      this.loading = true;
      this.error = null;
      try {
        const template = await watchdogApiService.getTemplate(id);

        // Update the template in the list with the full content,
        // preserving usage data that the single-template endpoint may not return
        const index = this.xsltTemplates.findIndex((t) => t.id === id);
        if (index !== -1) {
          const existing = this.xsltTemplates[index];
          this.xsltTemplates[index] = {
            ...existing,
            ...template,
            used_by_configs: template.used_by_configs ?? existing.used_by_configs,
            usage_count: template.usage_count ?? existing.usage_count,
          };
        }

        return template;
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to load XSLT template content';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    /**
     * Create a new XSLT template
     */
    async createXsltTemplate(input: XsltTemplateInput): Promise<XsltTemplate> {
      this.loading = true;
      this.error = null;
      try {
        const newTemplate = await watchdogApiService.createTemplate(input);
        // Ensure usage fields are initialized for new templates
        newTemplate.used_by_configs = newTemplate.used_by_configs ?? [];
        newTemplate.usage_count = newTemplate.usage_count ?? 0;
        this.xsltTemplates.push(newTemplate);
        return newTemplate;
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to create XSLT template';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    /**
     * Update an existing XSLT template
     */
    async updateXsltTemplate(
      id: string,
      input: Partial<XsltTemplateInput>,
    ): Promise<XsltTemplate> {
      this.loading = true;
      this.error = null;
      try {
        const updated = await watchdogApiService.updateTemplate(id, input);

        const index = this.xsltTemplates.findIndex((t) => t.id === id);
        if (index === -1) {
          throw new Error('XSLT template not found');
        }

        // Preserve usage data that the update endpoint may not return
        const existing = this.xsltTemplates[index];
        this.xsltTemplates[index] = {
          ...existing,
          ...updated,
          used_by_configs: updated.used_by_configs ?? existing.used_by_configs,
          usage_count: updated.usage_count ?? existing.usage_count,
        };
        return updated;
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to update XSLT template';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    /**
     * Delete an XSLT template
     * Throws error if template is in use by any configuration
     */
    async deleteXsltTemplate(id: string): Promise<void> {
      this.loading = true;
      this.error = null;
      try {
        const template = this.xsltTemplates.find((t) => t.id === id);
        if (!template) {
          throw new Error('XSLT template not found');
        }

        // Check if template is in use
        const usage = this.getTemplateUsage(id);
        if (usage.length > 0) {
          const configNames = usage.map((c) => c.name).join(', ');
          throw new Error(
            `Cannot delete template: in use by configurations: ${configNames}`,
          );
        }

        await watchdogApiService.deleteTemplate(id);

        this.xsltTemplates = this.xsltTemplates.filter((t) => t.id !== id);
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to delete XSLT template';
        throw err;
      } finally {
        this.loading = false;
      }
    },

    /**
     * Get list of configurations using a specific template
     */
    getTemplateUsage(templateId: string): WatchdogConfiguration[] {
      return this.configurations.filter(
        (c) => c.xslt_template_id === templateId,
      );
    },

    // ============================================
    // XSLT VALIDATION ACTIONS
    // ============================================

    /**
     * Load available document types for XSLT validation
     */
    async loadXsltDocTypes(): Promise<void> {
      try {
        this.xsltDocTypes = await watchdogApiService.getXsltDocTypes();
      } catch (err: unknown) {
        console.error('Failed to load XSLT doc types:', err);
        // Don't set error - this is a non-critical feature
      }
    },

    /**
     * Validate XSLT template against sample XML for a document type
     * @param xsltContent - XSLT stylesheet content to validate
     * @param docType - Optional document type to validate against
     * @returns Validation result with success/errors/warnings/field analysis
     */
    async validateXsltTemplate(
      xsltContent: string,
      docType?: string | null,
    ): Promise<XsltValidationResponse> {
      this.validationLoading = true;
      this.error = null;
      try {
        const result = await watchdogApiService.validateXsltTemplate({
          xslt_content: xsltContent,
          doc_type: docType,
        });
        return result;
      } catch (err: unknown) {
        const message =
          err instanceof Error
            ? err.message
            : 'Failed to validate XSLT template';
        this.error = message;
        // Return a failed validation response
        return {
          success: false,
          errors: [{ message }],
          warnings: [],
        };
      } finally {
        this.validationLoading = false;
      }
    },

    // ============================================
    // STATUS ACTIONS
    // ============================================

    /**
     * Load WatchDog service status
     */
    async loadStatus() {
      this.statusLoading = true;
      this.error = null;
      try {
        this.status = await watchdogApiService.getStatus();
      } catch (err: unknown) {
        this.error =
          err instanceof Error
            ? err.message
            : 'Failed to load WatchDog status';
      } finally {
        this.statusLoading = false;
      }
    },

    // ============================================
    // UI STATE ACTIONS
    // ============================================

    /**
     * Set the active tab
     */
    setActiveTab(tab: WatchdogTab) {
      this.activeTab = tab;
    },

    /**
     * Jump to XSLT tab and prepare to edit a specific template
     */
    jumpToXslt(id: string) {
      this.activeTab = 'xslt';
      this.targetXsltId = id;
    },

    /**
     * Clear the target XSLT ID after handling the jump
     */
    clearTargetXslt() {
      this.targetXsltId = null;
    },

    /**
     * Jump to configurations tab and prepare to edit a specific configuration
     */
    jumpToConfiguration(id: string) {
      this.activeTab = 'configurations';
      this.targetConfigId = id;
    },

    /**
     * Clear the target config ID after handling the jump
     */
    clearTargetConfig() {
      this.targetConfigId = null;
    },

    /**
     * Clear the current error
     */
    clearError() {
      this.error = null;
    },

    /**
     * Reset store to initial state
     */
    $reset() {
      this.loading = false;
      this.configurationsLoading = false;
      this.templatesLoading = false;
      this.statusLoading = false;
      this.validationLoading = false;
      this.configurations = [];
      this.xsltTemplates = [];
      this.status = null;
      this.xsltDocTypes = [];
      this.activeTab = 'general';
      this.targetXsltId = null;
      this.targetConfigId = null;
      this.error = null;
    },

    // ============================================
    // EXPORT/IMPORT ACTIONS
    // ============================================

    /**
     * Export configurations to JSON schema format
     * @param configIds - IDs of configs to export (empty = all)
     * @param includeTemplates - Whether to include XSLT templates
     */
    exportConfigurations(
      configIds: string[] = [],
      includeTemplates: boolean = false,
    ): WatchdogExportSchema {
      const configsToExport =
        configIds.length > 0
          ? this.configurations.filter((c) => configIds.includes(c.id))
          : this.configurations;

      // Convert to input format (strip server-generated fields)
      const configInputs: WatchdogConfigurationInput[] = configsToExport.map(
        (c) => ({
          name: c.name,
          config_type: c.config_type,
          sub_org_id: c.sub_org_id,
          doc_type_key: c.doc_type_key,
          import_path: c.import_path,
          success_path: c.success_path,
          export_path: c.export_path,
          xslt_template_id: includeTemplates ? c.xslt_template_id : null,
          export_type: c.export_type,
          export_config_id: c.export_config_id,
          // REST API fields
          rest_api_url: c.rest_api_url,
          method: c.method,
          username: c.username,
          password: c.password,
          body_type: c.body_type,
          rest_api_mapping: c.rest_api_mapping,
          // GLS840MI fields
          endpoint_name: c.endpoint_name,
          // Webhook fields
          webhook_url: c.webhook_url,
          is_default: c.is_default,
          is_active: c.is_active,
        }),
      );

      const schema: WatchdogExportSchema = {
        version: '1.0',
        exported_at: new Date().toISOString(),
        configurations: configInputs,
      };

      // Optionally include templates
      if (includeTemplates && this.xsltTemplates.length > 0) {
        schema.xslt_templates = this.xsltTemplates.map((t) => ({
          name: t.name,
          content: t.content,
        }));
      }

      return schema;
    },

    /**
     * Validate an import file without creating configs
     */
    validateImport(data: unknown): ImportValidationResult {
      const result: ImportValidationResult = {
        valid: true,
        configurations: [],
        warnings: [],
        errors: [],
        conflicts: [],
      };

      // Check it's an object
      if (!data || typeof data !== 'object') {
        result.valid = false;
        result.errors.push('Invalid JSON: expected an object');
        return result;
      }

      const schema = data as Record<string, unknown>;

      // Check version
      if (schema.version !== '1.0') {
        result.valid = false;
        result.errors.push(
          `Unsupported schema version: ${schema.version}. Expected 1.0`,
        );
        return result;
      }

      // Check configurations array
      if (!Array.isArray(schema.configurations)) {
        result.valid = false;
        result.errors.push('Missing or invalid configurations array');
        return result;
      }

      // Validate each configuration
      for (const config of schema.configurations) {
        if (!config.name || typeof config.name !== 'string') {
          result.errors.push('Configuration missing required field: name');
          result.valid = false;
          continue;
        }
        if (
          !config.config_type ||
          !['import', 'export'].includes(config.config_type)
        ) {
          result.errors.push(
            `Configuration "${config.name}" has invalid config_type`,
          );
          result.valid = false;
          continue;
        }

        // Check for conflicts with existing configs
        const existingConflict = this.configurations.find(
          (c) =>
            c.sub_org_id === config.sub_org_id &&
            c.doc_type_key === config.doc_type_key,
        );
        if (existingConflict) {
          result.conflicts.push({
            imported: config as WatchdogConfigurationInput,
            existing: existingConflict,
            reason: `Same sub-org and doc-type as existing config "${existingConflict.name}"`,
          });
        }

        // Clear xslt_template_id if templates not included (avoid broken refs)
        const configInput: WatchdogConfigurationInput = {
          ...config,
          xslt_template_id: null, // Always clear on import
          is_default: false, // Never import as default
        };

        result.configurations.push(configInput);
      }

      // Parse templates if included
      if (Array.isArray(schema.xslt_templates)) {
        result.xslt_templates = schema.xslt_templates.map((t: unknown) => {
          const template = t as Record<string, unknown>;
          return {
            name: String(template.name || ''),
            content: String(template.content || ''),
          };
        });
      }

      if (result.conflicts.length > 0) {
        result.warnings.push(
          `${result.conflicts.length} configuration(s) conflict with existing configs`,
        );
      }

      return result;
    },

    /**
     * Import configurations from validated schema
     * @param configs - Validated configurations to import
     * @param skipConflicts - If true, skip configs that conflict; if false, record error
     */
    async importConfigurations(
      configs: WatchdogConfigurationInput[],
      skipConflicts: boolean = true,
    ): Promise<ImportResult[]> {
      this.loading = true;
      this.error = null;
      const results: ImportResult[] = [];

      try {
        for (const config of configs) {
          // Check for conflict
          const existingConflict = this.configurations.find(
            (c) =>
              c.sub_org_id === config.sub_org_id &&
              c.doc_type_key === config.doc_type_key,
          );

          if (existingConflict) {
            if (skipConflicts) {
              results.push({
                name: config.name,
                success: false,
                skipped: true,
                error: `Skipped: conflicts with "${existingConflict.name}"`,
              });
              continue;
            } else {
              results.push({
                name: config.name,
                success: false,
                error: `Conflict with existing config "${existingConflict.name}"`,
              });
              continue;
            }
          }

          try {
            // Temporarily disable loading for individual creates
            this.loading = false;
            const created = await this.createConfiguration(config);
            results.push({
              name: config.name,
              success: true,
              config: created,
            });
          } catch (err) {
            results.push({
              name: config.name,
              success: false,
              error: err instanceof Error ? err.message : 'Unknown error',
            });
          }
        }

        return results;
      } finally {
        this.loading = false;
      }
    },

    // ============================================
    // V2 CONFIG IMPORT ACTIONS
    // ============================================

    /**
     * Detect if a JSON object is V2 or V3 format
     */
    detectConfigVersion(data: unknown): 'v2' | 'v3' {
      if (typeof data !== 'object' || data === null) return 'v3';

      const obj = data as Record<string, unknown>;

      // V3 export schema has version: "1.0" with configurations array
      if (obj.version === '1.0' && Array.isArray(obj.configurations)) return 'v3';

      // V3 internal format has version: "3.0"
      if (obj.version === '3.0') return 'v3';

      // V2 has no version, or version: "2.0", with read_dir/success_dir/export_folder
      if (
        obj.read_dir !== undefined ||
        obj.success_dir !== undefined ||
        (obj.export_folder !== undefined && !Array.isArray(obj.configurations))
      ) {
        return 'v2';
      }

      // Default to V3 for export schema format
      return 'v3';
    },

    /**
     * Convert V2 export_destination to V3 export_type
     * Note: V2 had infor/rest_api/gls840mi which now map to 'standard'
     */
    mapV2ExportDestination(dest?: string[]): WatchdogExportType {
      const firstDest = dest?.[0];
      if (!firstDest) return 'file';

      const mapping: Record<string, WatchdogExportType> = {
        folder: 'file',
        infor: 'standard',
        rest_api: 'standard',
        gls840mi: 'standard',
        webhook: 'standard',
      };
      return mapping[firstDest] || 'file';
    },

    /**
     * Validate a V2 config file and generate preview of V3 configs
     */
    validateV2Import(data: unknown): V2ImportValidationResult {
      const result: V2ImportValidationResult = {
        valid: true,
        detectedVersion: 'v2',
        previewConfigs: [],
        warnings: [],
        errors: [],
        unmigratableFields: [],
      };

      // First detect version
      result.detectedVersion = this.detectConfigVersion(data);
      if (result.detectedVersion === 'v3') {
        result.valid = false;
        result.errors.push('This appears to be a V3 config file. Use standard import instead.');
        return result;
      }

      // Validate it's an object
      if (!data || typeof data !== 'object') {
        result.valid = false;
        result.errors.push('Invalid JSON: expected an object');
        return result;
      }

      const v2Config = data as V2ConfigSchema;
      result.v2Config = v2Config;

      // Check minimum required fields
      if (!v2Config.read_dir && !v2Config.export_folder) {
        result.valid = false;
        result.errors.push('V2 config must have at least read_dir or export_folder');
        return result;
      }

      // Get doc_types or default to ["INVOICE"]
      const docTypes = v2Config.doc_types?.length ? v2Config.doc_types : ['INVOICE'];

      // Check for fields that won't be migrated
      const unmigratableFieldsMap: [string, unknown][] = [
        ['bod_mapping', v2Config.bod_mapping],
        ['username/password', v2Config.username || v2Config.password],
        ['headers', v2Config.headers],
        ['params', v2Config.params],
        ['api_key', v2Config.api_key],
        ['xslt', v2Config.xslt],
      ];

      for (const [fieldName, value] of unmigratableFieldsMap) {
        if (value && (typeof value !== 'object' || Object.keys(value as object).length > 0)) {
          result.unmigratableFields.push(fieldName);
        }
      }

      if (result.unmigratableFields.length > 0) {
        result.warnings.push(
          `The following fields will NOT be migrated and need manual reconfiguration: ${result.unmigratableFields.join(', ')}`,
        );
      }

      // Generate preview configs (one per doc_type)
      for (let i = 0; i < docTypes.length; i++) {
        const docType = docTypes[i];
        const name =
          docTypes.length === 1
            ? 'Migrated Configuration'
            : `Migrated Configuration - ${docType}`;

        // Check for conflict with existing configs
        const existingConflict = this.configurations.find(
          (c) => c.sub_org_id === null && c.doc_type_key === docType,
        );

        if (existingConflict) {
          result.warnings.push(
            `Config for doc_type "${docType}" conflicts with existing config "${existingConflict.name}"`,
          );
        }

        const previewConfig: WatchdogConfigurationInput = {
          name,
          config_type: v2Config.read_dir ? 'import' : 'export',
          sub_org_id: null,
          doc_type_key: docType,
          import_path: v2Config.read_dir || null,
          success_path: v2Config.success_dir || null,
          export_path: v2Config.export_folder || null,
          xslt_template_id: null, // V2 XSLT needs manual migration
          export_type: this.mapV2ExportDestination(v2Config.export_destination),
          is_default: false,
          is_active: true,
        };

        result.previewConfigs.push(previewConfig);
      }

      return result;
    },

    /**
     * Import a V2 config via the backend API
     */
    async importV2Config(v2Config: V2ConfigSchema): Promise<ImportResult[]> {
      this.loading = true;
      this.error = null;

      try {
        const response = await watchdogApiService.importV2Config(v2Config);

        // Add imported configs to local state
        for (const config of response.configurations) {
          const existingIndex = this.configurations.findIndex((c) => c.id === config.id);
          if (existingIndex === -1) {
            this.configurations.push(config);
          }
        }

        // Convert to ImportResult format for consistency with V3 import
        return response.configurations.map((config) => ({
          name: config.name,
          success: true,
          config,
        }));
      } catch (err: unknown) {
        this.error =
          err instanceof Error ? err.message : 'Failed to import V2 configuration';
        throw err;
      } finally {
        this.loading = false;
      }
    },
  },
});
