<template>
  <q-dialog
    :model-value="show"
    @update:model-value="$emit('update:show', $event)"
    no-backdrop-dismiss
    @escape-key="closeModal"
  >
    <q-card class="import-config-modal-card modern-card column no-wrap">
      <!-- Header -->
      <q-toolbar class="text-white secondary-toolbar modal-header">
        <q-toolbar-title>
          <span class="text-weight-bold">{{ t('import_configurations') }}</span>
        </q-toolbar-title>
        <q-btn icon="close" flat round dense color="white" @click="closeModal" />
      </q-toolbar>

      <q-card-section class="modal-content col scroll">
        <q-stepper
          v-model="currentStep"
          flat
          header-class="modern-stepper-header"
          color="primary"
          animated
        >
          <!-- Step 1: Upload File -->
          <q-step
            :name="1"
            :title="t('upload')"
            icon="upload_file"
            :done="currentStep > 1"
          >
            <div class="step-content">
              <div
                class="upload-zone row items-center justify-center q-pa-lg rounded-borders dashed-border q-mb-md"
                :class="{ 'drag-over': isDragOver }"
                @dragover.prevent="isDragOver = true"
                @dragenter.prevent="isDragOver = true"
                @dragleave.prevent="isDragOver = false"
                @drop.prevent="handleDrop"
              >
                <div class="column items-center">
                  <q-icon name="folder_zip" size="64px" color="primary" class="opacity-2 q-mb-md" />
                  <p class="text-subtitle1 text-weight-medium q-mb-md">{{ t('drag_drop_json') }}</p>
                  
                  <q-file
                    v-model="importFile"
                    outlined
                    dense
                    accept=".json"
                    class="hidden-input"
                    @update:model-value="handleFileUpload"
                    ref="fileInputRef"
                  />
                  
                  <q-btn
                    unelevated
                    color="primary"
                    :label="t('select_file')"
                    no-caps
                    class="rounded-pill q-px-xl"
                    @click="pickFile"
                  />
                </div>
              </div>

              <!-- File info after selection -->
              <q-slide-transition>
                <div v-if="importFile" class="modern-info-pill bg-blue-1 text-blue-9 q-pa-sm row items-center q-mb-md">
                  <q-icon name="description" size="24px" class="q-mr-md" />
                  <div class="column">
                    <span class="text-weight-bold">{{ importFile.name }}</span>
                    <span class="text-caption opacity-7">{{ formatFileSize(importFile.size) }}</span>
                  </div>
                  <q-space />
                  <q-icon name="check_circle" color="positive" size="20px" />
                </div>
              </q-slide-transition>

              <!-- Migration Banners -->
              <div class="banner-stack q-gutter-y-sm">
                <q-banner v-if="isV2Import && v2ValidationResult?.valid" class="bg-blue-1 text-blue-9 rounded-borders border-blue-2">
                  <template v-slot:avatar><q-icon name="auto_awesome" color="blue-7" /></template>
                  <div class="text-weight-bold">{{ t('v2_config_detected') }}</div>
                  <div class="text-caption">{{ t('v2_config_migration_info') }}</div>
                </q-banner>

                <q-banner v-if="validationResult && !validationResult.valid" class="bg-red-1 text-red-9 rounded-borders border-red-2">
                  <template v-slot:avatar><q-icon name="error_outline" color="red-7" /></template>
                  <div class="text-weight-bold">{{ t('invalid_import_file') }}</div>
                  <ul class="q-ma-none q-pl-md text-caption">
                    <li v-for="(error, idx) in validationResult.errors" :key="idx">{{ error }}</li>
                  </ul>
                </q-banner>
              </div>
            </div>

            <q-stepper-navigation class="row justify-end q-gutter-md q-pt-md">
              <q-btn flat :label="t('cancel')" color="grey-7" @click="closeModal" />
              <q-btn
                unelevated
                color="primary"
                :label="t('next')"
                class="rounded-pill q-px-xl"
                :disable="!canProceedToPreview"
                @click="currentStep = 2"
              />
            </q-stepper-navigation>
          </q-step>

          <!-- Step 2: Preview -->
          <q-step
            :name="2"
            :title="t('preview')"
            icon="visibility"
            :done="currentStep > 2"
          >
            <div class="step-content">
              <!-- Summary Grid -->
              <div class="row q-col-gutter-md q-mb-md">
                <div class="col-12 col-sm-6">
                  <q-card flat class="summary-stat-card bg-green-1 text-green-9">
                    <q-card-section class="row items-center no-wrap">
                      <div class="stat-icon bg-green-2 q-mr-md"><q-icon name="add_task" size="20px" /></div>
                      <div>
                        <div class="text-h5 text-weight-bold">{{ readyCount }}</div>
                        <div class="text-caption opacity-7">{{ t('ready_to_import') }}</div>
                      </div>
                    </q-card-section>
                  </q-card>
                </div>
                <div v-if="conflictCount > 0" class="col-12 col-sm-6">
                  <q-card flat class="summary-stat-card bg-amber-1 text-amber-9">
                    <q-card-section class="row items-center no-wrap">
                      <div class="stat-icon bg-amber-2 q-mr-md"><q-icon name="warning_amber" size="20px" /></div>
                      <div>
                        <div class="text-h5 text-weight-bold">{{ conflictCount }}</div>
                        <div class="text-caption opacity-7">{{ t('conflicts_detected') }}</div>
                      </div>
                    </q-card-section>
                  </q-card>
                </div>
              </div>

              <!-- Conflict resolution -->
              <div v-if="conflictCount > 0" class="bg-grey-1 q-pa-sm rounded-borders row items-center q-mb-md">
                <q-icon name="help_outline" color="grey-7" class="q-mr-sm" />
                <span class="text-body2 text-grey-8">{{ t('how_to_handle_conflicts') }}</span>
                <q-space />
                <q-toggle v-model="skipConflicts" :label="t('skip_conflicts')" color="primary" dense />
              </div>

              <!-- Preview table -->
              <DocBitsTable
                :rows="previewRows"
                :columns="previewColumns"
                row-key="name"
                dense
                class="modern-import-table"
                :features="{ sorting: false, pagination: false }"
              >
                <template #body-cell-status="{ row }">
                    <q-badge :color="getStatusColor(row.status) + '-1'" :text-color="getStatusColor(row.status) + '-9'" class="q-px-sm">
                      {{ t(row.status) }}
                    </q-badge>
                </template>
              </DocBitsTable>
            </div>

            <q-stepper-navigation class="row justify-end q-gutter-md q-pt-md">
              <q-btn flat :label="t('back')" color="grey-7" @click="currentStep = 1" />
              <q-btn
                unelevated
                color="primary"
                :label="t('execute_import')"
                class="rounded-pill q-px-xl shadow-2"
                :loading="processing"
                :disable="readyCount === 0"
                @click="executeImport"
              />
            </q-stepper-navigation>
          </q-step>

          <!-- Step 3: Result -->
          <q-step
            :name="3"
            :title="t('result')"
            icon="verified"
          >
            <div class="step-content text-center q-py-md">
              <q-icon 
                :name="successCount === importResults.length ? 'check_circle' : 'warning'" 
                :color="successCount === importResults.length ? 'positive' : 'warning'" 
                size="80px" 
                class="q-mb-lg" 
              />
              <div class="text-h5 text-weight-bold q-mb-sm">{{ t('import_finished') }}</div>
              <p class="text-subtitle1 text-grey-7 q-mb-md">
                {{ t('import_complete_summary', { success: successCount, total: importResults.length }) }}
              </p>

              <DocBitsTable
                v-if="importResults.length > 0"
                :rows="importResults"
                :columns="resultColumns"
                row-key="name"
                dense
                class="modern-import-table q-mx-auto"
                style="max-width: 600px"
                :features="{ sorting: false, pagination: false }"
              />
            </div>

            <q-stepper-navigation class="row justify-center q-pt-md">
              <q-btn
                unelevated
                color="primary"
                :label="t('done_return_to_configs')"
                class="rounded-pill q-px-xl"
                @click="finishImport"
              />
            </q-stepper-navigation>
          </q-step>
        </q-stepper>
      </q-card-section>
    </q-card>
  </q-dialog>
</template>

<script setup lang="ts">
import { ref, computed } from 'vue';
import { useTranslate } from '@tolgee/vue';
import DocBitsTable from 'src/components/Table/DocBitsTable.vue';
import { useWatchdogStore } from '../store/watchdog.store';
import type {
  ImportValidationResult,
  ImportResult,
  ImportConflict,
  V2ImportValidationResult,
  V2ConfigSchema,
} from '../types/watchdog.types';

const t = useTranslate().t;
const watchdogStore = useWatchdogStore();

// Refs
const fileInputRef = ref<any>(null);

// Props and emits
const props = defineProps<{
  show: boolean;
}>();

const emit = defineEmits<{
  (e: 'update:show', value: boolean): void;
  (e: 'completed'): void;
}>();

// State
const isDragOver = ref(false);
const currentStep = ref(1);
const importFile = ref<File | null>(null);
const validationResult = ref<ImportValidationResult | null>(null);
const v2ValidationResult = ref<V2ImportValidationResult | null>(null);
const detectedVersion = ref<'v2' | 'v3' | null>(null);
const rawParsedJson = ref<unknown>(null);
const skipConflicts = ref(true);
const processing = ref(false);
const importResults = ref<ImportResult[]>([]);
const importProgress = ref(0);

// Preview table columns
const previewColumns = computed(() => [
  {
    name: 'name',
    label: t.value('config_name'),
    field: 'name',
    align: 'left' as const,
  },
  {
    name: 'config_type',
    label: t.value('type'),
    field: 'config_type',
    align: 'left' as const,
  },
  {
    name: 'sub_org_id',
    label: t.value('sub_organization'),
    field: (row: { sub_org_id: string | null }) => row.sub_org_id === 'all_sub_orgs' || !row.sub_org_id ? t.value('all_sub_orgs') : row.sub_org_id,
    align: 'left' as const,
  },
  {
    name: 'doc_type_key',
    label: t.value('document_type'),
    field: (row: { doc_type_key: string | null }) => row.doc_type_key === 'all_types' || !row.doc_type_key ? t.value('all_types') : row.doc_type_key,
    align: 'left' as const,
  },
  {
    name: 'status',
    label: t.value('status'),
    field: 'status',
    align: 'center' as const,
  },
  {
    name: 'conflict_info',
    label: t.value('details'),
    field: 'conflict_info',
    align: 'left' as const,
  },
]);

// Results table columns
const resultColumns = computed(() => [
  {
    name: 'name',
    label: t.value('config_name'),
    field: 'name',
    align: 'left' as const,
  },
  {
    name: 'status',
    label: t.value('status'),
    field: 'status',
    align: 'center' as const,
  },
  {
    name: 'error',
    label: t.value('error'),
    field: 'error',
    align: 'left' as const,
  },
]);

// Computed
const canProceedToPreview = computed(() => {
  if (detectedVersion.value === 'v2') {
    return v2ValidationResult.value?.valid === true;
  }
  return validationResult.value?.valid === true;
});

const isV2Import = computed(() => detectedVersion.value === 'v2');

const previewRows = computed(() => {
  // Handle V2 import preview
  if (isV2Import.value && v2ValidationResult.value) {
    return v2ValidationResult.value.previewConfigs.map((config) => {
      // Check for conflicts based on doc_type_key
      const existingConflict = watchdogStore.configurations.find(
        (c) => c.sub_org_id === config.sub_org_id && c.doc_type_key === config.doc_type_key
      );
      let status = 'ready';
      if (existingConflict) {
        status = skipConflicts.value ? 'will_skip' : 'conflict';
      }
      return {
        ...config,
        status,
        conflict: existingConflict
          ? { imported: config, existing: existingConflict, reason: 'Duplicate' }
          : null,
      };
    });
  }

  // Handle V3 import preview
  if (!validationResult.value) return [];

  return validationResult.value.configurations.map((config) => {
    const conflict = validationResult.value?.conflicts.find(
      (c) => c.imported.name === config.name
    );
    let status = 'ready';
    if (conflict) {
      status = skipConflicts.value ? 'will_skip' : 'conflict';
    }
    return {
      ...config,
      status,
      conflict,
    };
  });
});

const readyCount = computed(() => {
  return previewRows.value.filter((r) => r.status === 'ready').length;
});

const conflictCount = computed(() => {
  if (isV2Import.value) {
    return previewRows.value.filter((r) => r.conflict).length;
  }
  return validationResult.value?.conflicts.length || 0;
});

const successCount = computed(() => {
  return importResults.value.filter((r) => r.success).length;
});

// Methods
const formatFileSize = (bytes: number): string => {
  if (bytes < 1024) return `${bytes} B`;
  if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
  return `${(bytes / (1024 * 1024)).toFixed(1)} MB`;
};

const getStatusColor = (status: string): string => {
  switch (status) {
    case 'ready':
      return 'positive';
    case 'conflict':
      return 'negative';
    case 'will_skip':
      return 'grey';
    default:
      return 'grey';
  }
};

const handleFileUpload = () => {
  if (!importFile.value) {
    validationResult.value = null;
    v2ValidationResult.value = null;
    detectedVersion.value = null;
    rawParsedJson.value = null;
    return;
  }

  const reader = new FileReader();
  reader.onload = (e) => {
    try {
      const json = JSON.parse(e.target?.result as string);
      rawParsedJson.value = json;

      // Detect config version
      detectedVersion.value = watchdogStore.detectConfigVersion(json);

      if (detectedVersion.value === 'v2') {
        // Validate as V2 config
        v2ValidationResult.value = watchdogStore.validateV2Import(json);
        validationResult.value = null;
      } else {
        // Validate as V3 export schema
        validationResult.value = watchdogStore.validateImport(json);
        v2ValidationResult.value = null;
      }
    } catch (err) {
      detectedVersion.value = null;
      validationResult.value = {
        valid: false,
        configurations: [],
        warnings: [],
        errors: ['Invalid JSON: ' + (err as Error).message],
        conflicts: [],
      };
      v2ValidationResult.value = null;
    }
  };
  reader.readAsText(importFile.value);
};

const executeImport = async () => {
  processing.value = true;
  currentStep.value = 3;
  importProgress.value = 0;

  try {
    if (isV2Import.value && v2ValidationResult.value?.v2Config) {
      // V2 import - send to backend for conversion
      importResults.value = await watchdogStore.importV2Config(
        v2ValidationResult.value.v2Config
      );
    } else if (validationResult.value) {
      // V3 import - use existing flow
      const configsToImport = skipConflicts.value
        ? validationResult.value.configurations.filter(
            (config) =>
              !validationResult.value?.conflicts.find(
                (c) => c.imported.name === config.name
              )
          )
        : validationResult.value.configurations;

      importResults.value = await watchdogStore.importConfigurations(
        configsToImport,
        skipConflicts.value
      );
    }
    importProgress.value = 1;
  } catch (err) {
    console.error('Import failed:', err);
    importResults.value = [{
      name: 'Import',
      success: false,
      error: err instanceof Error ? err.message : 'Unknown error',
    }];
  } finally {
    processing.value = false;
  }
};

const finishImport = () => {
  emit('completed');
  closeModal();
};

const closeModal = () => {
  // Reset state
  currentStep.value = 1;
  importFile.value = null;
  validationResult.value = null;
  v2ValidationResult.value = null;
  detectedVersion.value = null;
  rawParsedJson.value = null;
  skipConflicts.value = true;
  processing.value = false;
  importResults.value = [];
  importProgress.value = 0;

  emit('update:show', false);
};

const pickFile = () => {
  fileInputRef.value?.$el?.querySelector('input')?.click();
};

const handleDrop = (event: DragEvent) => {
  isDragOver.value = false;
  const file = event.dataTransfer?.files?.[0];
  if (file && file.name.endsWith('.json')) {
    importFile.value = file;
    handleFileUpload();
  }
};
</script>

