<script lang="ts">
import { notify } from 'src/components/notifications/notify';
import { defineComponent, type PropType } from 'vue';
import type {
  XsltTemplate,
  XsltTemplateInput,
  XsltValidationResponse,
  XsltDocType,
} from '../types/watchdog.types';
import { useWatchdogStore } from '../store/watchdog.store';
import { ApiExceptions } from 'src/exceptions';
import type { dynamicObj } from 'src/pages/assets';
// PrismJS imports for syntax highlighting
import { PrismEditor } from 'vue-prism-editor';
import 'vue-prism-editor/dist/prismeditor.min.css';
import { Prism } from 'src/utils/prism';

export default defineComponent({
  name: 'XsltTemplatesModal',

  components: {
    PrismEditor,
  },

  props: {
    modelValue: {
      type: Boolean,
      required: true,
    },
    templates: {
      type: Array as PropType<XsltTemplate[]>,
      required: true,
    },
    initialTemplateId: {
      type: String as PropType<string | null>,
      default: null,
    },
  },

  emits: ['update:modelValue', 'create', 'update', 'delete', 'selection-handled'],

  setup() {
    const watchdogStore = useWatchdogStore();
    return { watchdogStore };
  },

  data() {
    return {
      selectedTemplate: null as XsltTemplate | null,
      editingTemplate: null as { id?: string; name: string; content: string } | null,
      isNewTemplate: false,
      saving: false,
      showDeleteDialog: false,
      templateToDelete: null as XsltTemplate | null,
      deleting: false,
      selectedDocType: null as string | null,
      validationResult: null as XsltValidationResponse | null,
      showOutputPreview: false,
      loadingContent: false,
      docTypeOptions: [] as { label: string; value: string | null }[],
    };
  },

  watch: {
    'watchdogStore.xsltDocTypes': {
      handler() {
        this.buildDocTypeOptions();
      },
      immediate: true,
    },

    modelValue: {
      handler(isOpen: boolean) {
        if (isOpen && this.initialTemplateId) {
          const template = this.templates.find((t: XsltTemplate) => t.id === this.initialTemplateId);
          if (template) {
            this.selectTemplate(template);
            this.$emit('selection-handled');
          }
        } else if (!isOpen) {
          this.selectedTemplate = null;
          this.editingTemplate = null;
          this.isNewTemplate = false;
          this.loadingContent = false;
        }
      },
      immediate: true,
    },

    initialTemplateId(templateId: string | null) {
      if (this.modelValue && templateId) {
        const template = this.templates.find((t: XsltTemplate) => t.id === templateId);
        if (template) {
          this.selectTemplate(template);
          this.$emit('selection-handled');
        }
      }
    },
  },

  mounted() {
    if (this.watchdogStore.xsltDocTypes.length === 0) {
      this.watchdogStore.loadXsltDocTypes();
    }
  },

  methods: {
    highlighter(code: string): string {
      return Prism.highlight(code || '', Prism.languages.markup, 'markup');
    },

    buildDocTypeOptions() {
      const options: { label: string; value: string | null }[] = [
        { label: this.$t('generic_any_doc_type'), value: null },
      ];
      this.watchdogStore.xsltDocTypes.forEach((dt: XsltDocType) => {
        options.push({
          label: dt.label,
          value: dt.value,
        });
      });
      this.docTypeOptions = options;
    },

    closeModal() {
      this.$emit('update:modelValue', false);
    },

    async selectTemplate(template: XsltTemplate) {
      this.selectedTemplate = template;
      this.isNewTemplate = false;
      this.validationResult = null;
      this.showOutputPreview = false;

      if (!template.content) {
        this.loadingContent = true;
        try {
          const fullTemplate = await this.watchdogStore.loadXsltTemplateContent(template.id);
          this.selectedTemplate = fullTemplate;
          this.editingTemplate = {
            id: fullTemplate.id,
            name: fullTemplate.name,
            content: fullTemplate.content,
          };
        } catch (err) {
          const msg = ApiExceptions.getErrorMessage(err as dynamicObj);
          logError(err, msg);
          notify.error(msg);
          this.editingTemplate = {
            id: template.id,
            name: template.name,
            content: '',
          };
        } finally {
          this.loadingContent = false;
        }
      } else {
        this.editingTemplate = {
          id: template.id,
          name: template.name,
          content: template.content,
        };
      }
    },

    createNewTemplate() {
      this.selectedTemplate = null;
      this.editingTemplate = {
        name: '',
        content: '',
      };
      this.isNewTemplate = true;
      this.validationResult = null;
      this.showOutputPreview = false;
    },

    duplicateTemplate(template: XsltTemplate) {
      this.selectedTemplate = null;
      this.editingTemplate = {
        name: `${template.name} (Copy)`,
        content: template.content,
      };
      this.isNewTemplate = true;
    },

    cancelEdit() {
      if (this.selectedTemplate) {
        this.editingTemplate = {
          id: this.selectedTemplate.id,
          name: this.selectedTemplate.name,
          content: this.selectedTemplate.content,
        };
      } else {
        this.editingTemplate = null;
      }
      this.isNewTemplate = false;
    },

    async saveTemplate() {
      if (!this.editingTemplate || !this.editingTemplate.name || !this.editingTemplate.content) {
        return;
      }

      this.saving = true;
      try {
        if (this.isNewTemplate) {
          this.$emit('create', {
            name: this.editingTemplate.name,
            content: this.editingTemplate.content,
          } as XsltTemplateInput);
          this.editingTemplate = null;
          this.isNewTemplate = false;
        } else if (this.editingTemplate.id) {
          this.$emit('update', this.editingTemplate.id, {
            name: this.editingTemplate.name,
            content: this.editingTemplate.content,
          });
        }
      } finally {
        this.saving = false;
      }
    },

    async validateTemplate() {
      if (!this.editingTemplate?.content) {
        return;
      }

      this.validationResult = await this.watchdogStore.validateXsltTemplate(
        this.editingTemplate.content,
        this.selectedDocType,
      );
      this.showOutputPreview = false;
    },

    confirmDeleteTemplate(template: XsltTemplate) {
      if (template.usage_count > 0) {
        return;
      }
      this.templateToDelete = template;
      this.showDeleteDialog = true;
    },

    async executeDelete() {
      if (!this.templateToDelete) return;

      this.deleting = true;
      try {
        this.$emit('delete', this.templateToDelete.id);
        this.showDeleteDialog = false;

        if (this.selectedTemplate?.id === this.templateToDelete.id) {
          this.selectedTemplate = null;
          this.editingTemplate = null;
        }

        this.templateToDelete = null;
      } finally {
        this.deleting = false;
      }
    },

    goToConfig(configId: string) {
      this.closeModal();
      this.watchdogStore.jumpToConfiguration(configId);
    },
  },
});
</script>

