<template>
  <q-drawer
    :model-value="open"
    @update:model-value="$emit('close')"
    side="right"
    overlay
    :width="450"
  >
    <q-scroll-area class="fit">
      <div class="q-pa-md">
        <!-- Header -->
        <div class="row items-center q-mb-md">
          <div class="text-h6">{{ t('watchdog_setup_title') }}</div>
          <q-space />
          <q-btn flat dense round icon="close" @click="$emit('close')" />
        </div>

        <!-- Subtitle -->
        <p class="text-body2 text-grey-7 q-mb-lg">
          {{ t('watchdog_setup_subtitle') }}
        </p>

        <!-- Step 1: Download -->
        <q-card flat bordered class="q-mb-md">
          <q-card-section>
            <div class="row items-start">
              <q-avatar color="primary" text-color="white" size="32px" class="q-mr-md">
                1
              </q-avatar>
              <div class="col">
                <div class="text-subtitle1 text-weight-medium">
                  {{ t('watchdog_setup_step1_title') }}
                </div>
                <p class="text-body2 text-grey-7 q-mb-sm">
                  {{ t('watchdog_setup_step1_desc') }}
                </p>
                <f-btn
                  appearance="secondary"
                  :label="t('watchdog_setup_download')"
                  @click="openDownload"
                >
                  <template v-slot:icon>
                    <Icon icon="mdi:github" width="20" height="20" class="q-mr-sm" />
                  </template>
                </f-btn>
              </div>
            </div>
          </q-card-section>
        </q-card>

        <!-- Step 2: Install -->
        <q-card flat bordered class="q-mb-md">
          <q-card-section>
            <div class="row items-start">
              <q-avatar color="primary" text-color="white" size="32px" class="q-mr-md">
                2
              </q-avatar>
              <div class="col">
                <div class="text-subtitle1 text-weight-medium">
                  {{ t('watchdog_setup_step2_title') }}
                </div>
                <p class="text-body2 text-grey-7 q-mb-none">
                  {{ t('watchdog_setup_step2_desc') }}
                </p>
              </div>
            </div>
          </q-card-section>
        </q-card>

        <!-- Step 3: Configure -->
        <q-card flat bordered class="q-mb-md">
          <q-card-section>
            <div class="row items-start">
              <q-avatar color="primary" text-color="white" size="32px" class="q-mr-md">
                3
              </q-avatar>
              <div class="col">
                <div class="text-subtitle1 text-weight-medium">
                  {{ t('watchdog_setup_step3_title') }}
                </div>
                <p class="text-body2 text-grey-7 q-mb-sm">
                  {{ t('watchdog_setup_step3_desc') }}
                </p>
                <!-- Command display with copy button -->
                <div class="text-caption text-grey-6 q-mb-xs">
                  {{ t('watchdog_setup_command_label') }}
                </div>
                <div class="row items-center">
                  <q-input
                    :model-value="command"
                    outlined
                    readonly
                    dense
                    class="col command-input"
                  />
                  <f-btn
                    class="q-ml-sm"
                    :icon="copyIcon"
                    @click="handleCopy"
                  >
                    <q-tooltip>
                      {{ copied ? t('watchdog_setup_copied') : t('watchdog_setup_copy_tooltip') }}
                    </q-tooltip>
                  </f-btn>
                </div>
              </div>
            </div>
          </q-card-section>
        </q-card>

        <!-- Step 4: Verify -->
        <q-card flat bordered class="q-mb-md">
          <q-card-section>
            <div class="row items-start">
              <q-avatar color="primary" text-color="white" size="32px" class="q-mr-md">
                4
              </q-avatar>
              <div class="col">
                <div class="text-subtitle1 text-weight-medium">
                  {{ t('watchdog_setup_step4_title') }}
                </div>
                <p class="text-body2 text-grey-7 q-mb-none">
                  {{ t('watchdog_setup_step4_desc') }}
                </p>
              </div>
            </div>
          </q-card-section>
        </q-card>

        <!-- Troubleshooting link -->
        <div class="q-mt-lg text-center">
          <p class="text-body2 text-grey-7 q-mb-sm">
            {{ t('watchdog_setup_troubleshooting') }}
          </p>
          <a :href="docsUrl" target="_blank" class="text-primary">
            {{ t('watchdog_setup_docs_link') }}
          </a>
        </div>
      </div>
    </q-scroll-area>
  </q-drawer>
</template>

<script setup lang="ts">

import { ref, computed } from 'vue';
import { copyToClipboard } from 'quasar';
import { useTranslate } from '@tolgee/vue';
import {
  WATCHDOG_RELEASES_PAGE,
  buildWatchdogSetupCommand,
} from '../watchdogSetup';

const t = useTranslate().t;

const props = defineProps<{
  open: boolean;
  apiKey: string;
}>();

defineEmits<{
  (e: 'close'): void;
}>();

// Constants
const docsUrl = 'https://docs.docbits.com/watchdog';

// Computed
// Same two environment-scoped artefacts as the General tab (DOCB-14033): the
// download points at the release listing rather than a bucket path that serves
// no installer, and the key carries this environment's prefix so WatchDog talks
// to the right API host.
const downloadUrl = WATCHDOG_RELEASES_PAGE;
const command = computed(() => buildWatchdogSetupCommand(props.apiKey));

// Copy state
const copyIcon = ref('content_copy');
const copied = ref(false);

async function handleCopy() {
  await copyToClipboard(command.value);
  copyIcon.value = 'check';
  copied.value = true;
  setTimeout(() => {
    copyIcon.value = 'content_copy';
    copied.value = false;
  }, 2000);
}

function openDownload() {
  window.open(downloadUrl, '_blank');
}
</script>

<style scoped lang="scss">
.command-input {
  font-family: monospace;
}
</style>
