/**
 * WatchDog setup helpers — download URL + setup command construction.
 *
 * Both artefacts the WatchDog settings page shows the customer are
 * environment-scoped, and both were building that scope wrong (DOCB-14033):
 *
 *  1. **Download link.** WatchDog builds are published per environment as
 *     `builds/WatchDog_<env>-<version>.exe` (see the WatchDog repo's
 *     `.github/workflows/release.yaml`, which tags every release
 *     `<env>-<version>` and uploads it under that exact name). The API
 *     (`/resource/watchdog-releases`) returns the *bare* version — the tag with
 *     the `<env>-` prefix stripped — so rebuilding a file name from that version
 *     alone produces `WatchDog_2.18.5.195.exe`, a file that exists for no
 *     environment. The URL must be rebuilt with the environment tag.
 *
 *  2. **Setup command.** WatchDog derives the API host it talks to from the
 *     *prefix of the API key* it is handed (`src/cli/config_fetcher.py`:
 *     `dev_` → `https://dev.api.docbits.com`, `us_`/`eu_` prepended as a region
 *     subdomain, no prefix → production `https://api.docbits.com`). Handing the
 *     customer the raw integration token therefore points every non-production
 *     installation at production.
 *
 * The environment is taken from the same mechanism every other DocBits host in
 * this app uses — `getBranchPrefix()` / `getCurrentApiRegion()` /
 * `isRegionalStage()` from `src/pages/api-base-url` — so nothing here is pinned
 * to a single environment. `watchdog-files.docbits.com` and
 * `watchdog.docbits.com` are *global* hosts (one bucket, one release page, for
 * all environments); the environment lives in the file name, not the host.
 */

import {
  getBranchPrefix,
  getCurrentApiRegion,
  isRegionalStage,
  type ApiRegion,
} from 'src/pages/api-base-url';

/** CDN in front of the `docbits-watchdog` Spaces bucket that holds the builds. */
export const WATCHDOG_FILES_HOST = 'https://watchdog-files.docbits.com';

/** Human-facing release listing (used when no concrete build is known yet). */
export const WATCHDOG_RELEASES_PAGE = 'https://watchdog.docbits.com/';

/**
 * The environments the WatchDog release pipeline actually publishes builds for
 * (the `target_environment` choices of its release workflow). Any other branch
 * this app can be built for has no builds of its own.
 */
export const RELEASE_ENVIRONMENTS = [
  'dev',
  'stage',
  'demo',
  'sandbox',
  'prod',
] as const;

export type ReleaseEnvironment = (typeof RELEASE_ENVIRONMENTS)[number];

/** Service commands accepted by WatchDog.exe (see its CLI parser). */
export const WATCHDOG_SERVICE_INSTALL_COMMAND = 'WatchDog.exe install';
export const WATCHDOG_SERVICE_START_COMMAND = 'WatchDog.exe start';

/** Placeholder rendered while the org's integration key is still loading. */
export const API_KEY_PLACEHOLDER = 'YOUR_API_KEY';

/**
 * The build branch this app was compiled for, without the trailing dot —
 * `'dev'`, `'stage'`, `'pre-prod'`, … and `''` for production.
 */
export function getCurrentBranch(branchPrefix: string = getBranchPrefix()): string {
  return branchPrefix.endsWith('.') ? branchPrefix.slice(0, -1) : branchPrefix;
}

/**
 * Map a build branch onto the environment whose WatchDog builds it should
 * offer. Production (`''`) and every branch without its own release track
 * (`pre-prod`, one-off branches) fall back to `prod`, the only track that is
 * always published; suffixed variants of a real track (`dev-hf`,
 * `sandbox-legacy`, …) use that track's builds.
 */
export function resolveReleaseEnvironment(
  branch: string = getCurrentBranch(),
): ReleaseEnvironment {
  const normalized = branch.trim().toLowerCase();
  if (!normalized) return 'prod';

  const exact = RELEASE_ENVIRONMENTS.find((env) => env === normalized);
  if (exact) return exact;

  const base = RELEASE_ENVIRONMENTS.find((env) =>
    normalized.startsWith(`${env}-`),
  );
  return base ?? 'prod';
}

/**
 * The download URL of a concrete build: the release tag is always
 * `<env>-<version>`, so the asset is `WatchDog_<env>-<version>.exe`.
 */
export function buildWatchdogBuildUrl(
  version: string,
  environment: ReleaseEnvironment = resolveReleaseEnvironment(),
): string {
  return `${WATCHDOG_FILES_HOST}/builds/WatchDog_${environment}-${version}.exe`;
}

/** A version string that identifies no build (absent, blank, or the API's "N/A"). */
export function isUsableVersion(version: string | null | undefined): boolean {
  const trimmed = (version ?? '').trim();
  return trimmed.length > 0 && trimmed.toUpperCase() !== 'N/A';
}

/**
 * Resolve what the download link should point at.
 *
 * The API's own `download_url` wins — it is built from the full release tag and
 * is therefore authoritative. Without it we rebuild the URL from the newest
 * version the API reported *for this environment*, and only when even that is
 * missing do we fall back to the release listing. We never emit a URL for a
 * version we were not told exists.
 */
export function resolveWatchdogDownloadUrl(release: {
  version?: string | null;
  downloadUrl?: string | null;
  environment?: ReleaseEnvironment;
}): string {
  const apiUrl = (release.downloadUrl ?? '').trim();
  if (apiUrl) return apiUrl;

  if (isUsableVersion(release.version)) {
    return buildWatchdogBuildUrl(
      (release.version as string).trim(),
      release.environment ?? resolveReleaseEnvironment(),
    );
  }

  return WATCHDOG_RELEASES_PAGE;
}

/** True when the URL points at a concrete installer rather than a listing page. */
export function isDownloadableBuildUrl(url: string | null | undefined): boolean {
  return (url ?? '').trim().toLowerCase().endsWith('.exe');
}

/**
 * The `<env>_` prefix WatchDog expects on the API key, e.g. `dev_`. Empty on
 * production, where the un-prefixed key already resolves to `api.docbits.com`.
 */
export function getApiKeyEnvironmentPrefix(
  branch: string = getCurrentBranch(),
): string {
  const normalized = branch.trim().toLowerCase();
  return normalized ? `${normalized}_` : '';
}

/**
 * The `<region>_` prefix, e.g. `eu_`. Only regional stages have regional API
 * hosts — on stage/demo/local a region prefix would resolve to a host that
 * does not exist.
 */
export function getApiKeyRegionPrefix(
  region: ApiRegion = getCurrentApiRegion(),
  regional: boolean = isRegionalStage(),
): string {
  return regional ? `${region}_` : '';
}

/**
 * Prefix the org's integration key so WatchDog resolves the API host of *this*
 * environment and region. Already-prefixed keys are passed through untouched so
 * a backend that starts issuing scoped keys never yields `dev_dev_…`.
 */
export function buildEnvironmentScopedApiKey(
  apiKey: string,
  opts: { branch?: string; region?: ApiRegion; regional?: boolean } = {},
): string {
  const key = (apiKey ?? '').trim();
  if (!key) return '';

  const envPrefix = getApiKeyEnvironmentPrefix(opts.branch ?? getCurrentBranch());
  const regionPrefix = getApiKeyRegionPrefix(
    opts.region ?? getCurrentApiRegion(),
    opts.regional ?? isRegionalStage(),
  );

  const alreadyScoped =
    (!!regionPrefix && key.startsWith(regionPrefix)) ||
    (!!envPrefix && key.startsWith(envPrefix));
  if (alreadyScoped) return key;

  return `${regionPrefix}${envPrefix}${key}`;
}

/**
 * The PowerShell command the customer copies. Shows the placeholder — never a
 * half-built command — while the key is still loading.
 */
export function buildWatchdogSetupCommand(
  apiKey: string,
  opts: { branch?: string; region?: ApiRegion; regional?: boolean } = {},
): string {
  const scopedKey = buildEnvironmentScopedApiKey(apiKey, opts);
  return `WatchDog.exe -api ${scopedKey || API_KEY_PLACEHOLDER}`;
}

/** True once the command carries a real key rather than the placeholder. */
export function isRunnableSetupCommand(command: string | null | undefined): boolean {
  const value = (command ?? '').trim();
  return value.length > 0 && !value.includes(API_KEY_PLACEHOLDER);
}
