<template>
  <div class="watchdog-logs-container">
    <div class="row items-center justify-between q-mb-md">
      <div>
        <div class="text-h5 text-weight-bold text-primary">{{ $t('watchdog_logs') }}</div>
        <div class="text-subtitle2 text-grey-7">{{ $t('watchdog_logs_description') }}</div>
      </div>
      <div class="row items-center q-gutter-sm">
        <!-- Client-side filters: narrow down the already-loaded logs (instant, no refetch) -->
        <q-input
          dense
          outlined
          clearable
          v-model="searchText"
          :placeholder="$t('search_logs')"
          debounce="300"
          style="min-width: 220px"
        >
          <template v-slot:prepend>
            <q-icon name="search" />
          </template>
        </q-input>
        <q-select
          dense
          outlined
          multiple
          emit-value
          map-options
          use-chips
          v-model="selectedLevels"
          :options="levelOptions"
          :label="$t('log_level')"
          style="min-width: 200px"
        >
          <template v-slot:option="{ itemProps, selected, opt, toggleOption }">
            <q-item v-bind="itemProps">
              <q-item-section side>
                <q-checkbox
                  :model-value="selected"
                  @update:model-value="toggleOption(opt)"
                />
              </q-item-section>
              <q-item-section>
                <div>{{ opt.label }}</div>
              </q-item-section>
            </q-item>
          </template>
        </q-select>

        <q-separator vertical inset class="q-mx-xs" />

        <!-- Data-fetch controls: change what is loaded from the server -->
        <q-select
          outlined
          dense
          v-model="timeRangeHours"
          :options="timeRangeOptions"
          emit-value
          map-options
          :label="$t('time_range')"
          style="min-width: 150px"
        />
        <q-btn
          flat
          dense
          round
          icon="refresh"
          :loading="loading"
          @click="loadLogs"
        >
          <q-tooltip>{{ $t('refresh_logs') }}</q-tooltip>
        </q-btn>
      </div>
    </div>
    <div class="card-content">

        <!-- Error state -->
        <div v-if="error" class="text-center text-negative q-py-lg">
          <q-icon name="error_outline" size="32px" class="q-mb-sm" />
          <div>{{ error }}</div>
          <q-btn
            flat
            color="primary"
            :label="$t('retry')"
            @click="loadLogs"
            class="q-mt-sm"
          />
        </div>

        <!-- Logs table using DocBitsTable -->
        <DocBitsTable
          v-else
          :rows="paginatedLogs"
          :columns="tableColumns"
          row-key="timestamp"
          table-id="watchdog_logs_table"
          :loading="loading"
          table-height="calc(100vh - 310px)"
          :features="{
            sorting: false,
            filtering: false,
            pagination: false,
            selection: false,
            rowActions: false,
            stickyFirstColumn: false,
            stickyLastColumn: false,
          }"
          :empty-message="t('no_logs_available')"
          flat
          dense
        >
          <!-- Custom timestamp cell -->
          <template #body-cell-timestamp="{ row }">
            <span class="font-mono text-caption">{{ formatTimestamp(row.timestamp) }}</span>
          </template>

          <!-- Custom level cell with badge -->
          <template #body-cell-level="{ row }">
            <q-badge :color="getLevelColor(row.level)" class="level-badge">
              {{ row.level }}
            </q-badge>
          </template>

          <!-- Custom message cell -->
          <template #body-cell-message="{ row }">
            <div class="message-cell">{{ row.message }}</div>
          </template>
        </DocBitsTable>

        <!-- Pagination footer -->
        <div v-if="filteredLogs.length > 0" class="row items-center justify-between q-px-sm q-pt-sm">
          <div class="row items-center q-gutter-md">
            <div class="text-caption text-grey-7">
              {{ (currentPage - 1) * pageSize + 1 }}–{{ Math.min(currentPage * pageSize, filteredLogs.length) }}
              of {{ filteredLogs.length }} logs
            </div>
            <div class="row items-center">
              <span class="q-mr-sm text-caption">{{ $t('logs_per_page') }}:</span>
              <q-select
                outlined
                dense
                v-model="pageSize"
                :options="pageSizeOptions"
                emit-value
                map-options
                style="min-width: 80px"
              />
            </div>
          </div>
          <q-pagination
            v-if="totalPages > 1"
            v-model="currentPage"
            :max="totalPages"
            :max-pages="6"
            input
            boundary-numbers
            direction-links
            dense
            color="primary"
          />
        </div>
    </div>
  </div>
</template>

<script lang="ts">
import { defineComponent } from 'vue';
import { useTranslate } from '@tolgee/vue';
import type { OrganizationLogEntry } from 'src/generated-api-sdk/models/OrganizationLogEntry';
import type { OrganizationLogsResponse } from 'src/generated-api-sdk/models/OrganizationLogsResponse';
import { OpenAPI } from 'src/generated-api-sdk/core/OpenAPI';
import { request as __request } from 'src/generated-api-sdk/core/request';
import { DocBitsTable } from 'src/components/Table';
import type { UnifiedTableColumn } from 'src/components/Table';

// The backend now returns cursor pagination fields that aren't in the generated SDK yet.
type PaginatedLogsResponse = OrganizationLogsResponse & {
  pagination?: {
    next_cursor?: string | null;
    has_next_page?: boolean;
  };
};

const LOGS_PAGE_SIZE = 10000;

// `metadata` is a free-form object; walk it defensively so a deeply nested (or
// self-referential) payload can never lock up the search.
const METADATA_SEARCH_MAX_DEPTH = 5;

export default defineComponent({
  name: 'WatchdogLogsCard',

  components: { DocBitsTable },

  setup() {
    const { t } = useTranslate();
    return { t };
  },

  data() {
    return {
      pageSizeOptions: [100, 250, 500, 1000, 2500],
      loading: false,
      error: null as string | null,
      logs: [] as OrganizationLogEntry[],
      currentPage: 1,
      pageSize: 500,
      timeRangeHours: 48,
      selectedLevels: [] as string[],
      searchText: '',
    };
  },

  computed: {
    timeRangeOptions(): { label: string; value: number }[] {
      return [
        { label: this.t('last_24_hours'), value: 24 },
        { label: this.t('last_48_hours'), value: 48 },
        { label: this.t('last_7_days'), value: 168 },
      ];
    },

    // Log level filter — each option matches all its variants (e.g. WARN/WARNING).
    levelOptions(): { label: string; value: string }[] {
      return [
        { label: this.t('info'), value: 'INFO' },
        { label: this.t('warnings'), value: 'WARNING' },
        { label: this.t('error'), value: 'ERROR' },
      ];
    },

    filteredLogs(): OrganizationLogEntry[] {
      const search = this.searchText?.trim().toLowerCase() ?? '';
      const hasLevelFilter = !!this.selectedLevels?.length;
      if (!hasLevelFilter && !search) return this.logs;

      return this.logs.filter((log: OrganizationLogEntry) => {
        if (hasLevelFilter && !this.selectedLevels.includes(this.normalizeLevel(log.level))) {
          return false;
        }
        if (search && !this.logMatchesSearch(log, search)) {
          return false;
        }
        return true;
      });
    },

    totalPages(): number {
      return Math.ceil(this.filteredLogs.length / this.pageSize);
    },

    paginatedLogs(): OrganizationLogEntry[] {
      return this.filteredLogs.slice(
        (this.currentPage - 1) * this.pageSize,
        this.currentPage * this.pageSize,
      );
    },

    tableColumns(): UnifiedTableColumn[] {
      return [
        {
          name: 'timestamp',
          label: this.t('log_timestamp'),
          field: 'timestamp',
          align: 'left',
          style: 'width: 200px; min-width: 200px;',
          sortable: false,
        },
        {
          name: 'level',
          label: this.t('log_level'),
          field: 'level',
          align: 'left',
          style: 'width: 100px',
          sortable: false,
        },
        {
          name: 'message',
          label: this.t('message'),
          field: 'message',
          align: 'left',
          sortable: false,
        },
      ];
    },
  },

  watch: {
    pageSize() {
      this.currentPage = 1;
    },
    selectedLevels() {
      this.currentPage = 1;
    },
    searchText() {
      this.currentPage = 1;
    },
    timeRangeHours() {
      void this.loadLogs();
    },
  },

  mounted() {
    void this.loadLogs();
  },

  methods: {
    fetchLogsPage(cursor?: string) {
      return __request<PaginatedLogsResponse>(OpenAPI, {
        method: 'GET',
        url: '/api/logs/organization',
        query: {
          services: 'watchdog',
          hours: this.timeRangeHours,
          page_size: LOGS_PAGE_SIZE,
          ...(cursor ? { cursor } : {}),
        },
        errors: {
          400: 'Bad Request',
          401: 'Unauthorized',
          403: 'Forbidden',
          422: 'Validation Error',
          429: 'Too Many Requests',
          503: 'Service Unavailable',
        },
      });
    },

    async loadLogs() {
      this.loading = true;
      this.error = null;
      this.currentPage = 1;

      try {
        const aggregated: OrganizationLogEntry[] = [];
        let cursor: string | undefined;

        do {
          const response = await this.fetchLogsPage(cursor);
          if (response.logs?.length) aggregated.push(...response.logs);
          cursor = response.pagination?.next_cursor ?? undefined;
        } while (cursor);

        this.logs = aggregated;
      } catch (err) {
        console.error('[WatchdogLogsCard] Failed to fetch logs:', err);
        this.error = this.t('error_loading_logs');
        this.logs = [];
      } finally {
        this.loading = false;
      }
    },

    formatTimestamp(timestamp: string): string {
      try {
        const date = new Date(timestamp);
        return date.toLocaleString('en-US', {
          year: 'numeric',
          month: 'short',
          day: '2-digit',
          hour: '2-digit',
          minute: '2-digit',
          second: '2-digit',
          hour12: false,
        });
      } catch {
        return timestamp;
      }
    },

    getLevelColor(level: string): string {
      switch (level.toUpperCase()) {
        case 'ERROR':
          return 'negative';
        case 'WARN':
        case 'WARNING':
          return 'warning';
        case 'INFO':
          return 'info';
        case 'DEBUG':
          return 'grey-6';
        default:
          return 'grey';
      }
    },

    // Collect the primitive *values* of a free-form metadata payload (keys are
    // internal field names and would only produce noise matches).
    collectMetadataValues(value: unknown, out: string[], depth = 0): void {
      if (value === null || value === undefined) return;
      if (depth > METADATA_SEARCH_MAX_DEPTH) return;

      if (Array.isArray(value)) {
        for (const item of value) this.collectMetadataValues(item, out, depth + 1);
        return;
      }
      if (typeof value === 'object') {
        for (const item of Object.values(value as Record<string, unknown>)) {
          this.collectMetadataValues(item, out, depth + 1);
        }
        return;
      }
      out.push(String(value));
    },

    // Search matches the message, the emitting service, and the metadata values —
    // document IDs are only ever carried in metadata, never in the message.
    logMatchesSearch(log: OrganizationLogEntry, search: string): boolean {
      if ((log.message || '').toLowerCase().includes(search)) return true;
      if ((log.service || '').toLowerCase().includes(search)) return true;

      const values: string[] = [];
      this.collectMetadataValues(log.metadata, values);
      return values.some((value) => value.toLowerCase().includes(search));
    },

    // Normalize a raw log level to one of the filter values (INFO / WARNING / ERROR).
    normalizeLevel(level: string | undefined): string {
      switch ((level || '').toUpperCase()) {
        case 'ERROR':
          return 'ERROR';
        case 'WARN':
        case 'WARNING':
          return 'WARNING';
        case 'INFO':
          return 'INFO';
        default:
          return 'INFO';
      }
    },
  },
});
</script>

