<template>
  <div>
    <Loader />

    <div class="watchdog-settings-container q-pb-xl">
      <!-- Modern Navigation Tabs -->
      <div class="row justify-center">
        <div class="col-12">
          <q-tabs
            v-model="activeTab"
            class="bg-white text-grey-7 shadow-1 rounded-borders q-mb-md navigation-tabs"
            active-color="primary"
            indicator-color="primary"
            align="left"
            narrow-indicator
            no-caps
          >
            <q-tab name="general" :label="$t('general')" icon="dashboard" class="q-px-lg" />
            <q-tab name="configurations" :label="$t('configurations')" icon="tune" class="q-px-lg" />
            <q-tab name="status" :label="$t('logs')" icon="assignment" class="q-px-lg" />
            <q-tab name="xslt" :label="$t('xslt_templates')" icon="code" class="q-px-lg" />
          </q-tabs>

          <q-tab-panels
            v-model="activeTab"
            animated
            transition-prev="fade"
            transition-next="fade"
            class="bg-transparent"
          >
            <q-tab-panel name="general" class="q-pa-none">
              <GeneralTab />
            </q-tab-panel>

            <q-tab-panel name="configurations" class="q-pa-none">
              <ExportConfigurationsCard
                ref="exportConfigCard"
                :doc-types="docTypes"
                :sub-orgs="subOrgs"
              />
            </q-tab-panel>

            <q-tab-panel name="status" class="q-pa-none">
              <WatchdogLogsCard />
            </q-tab-panel>

            <q-tab-panel name="xslt" class="q-pa-none">
              <XsltTemplatesTab />
            </q-tab-panel>
          </q-tab-panels>
        </div>
      </div>
    </div>

    <!-- Setup Help Drawer -->
    <WatchdogSetupDrawer
      :open="showSetupDrawer"
      :api-key="setupApiKey"
      @close="showSetupDrawer = false"
    />
  </div>
</template>

<script setup lang="ts">
import { ref, onMounted, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import { storeToRefs } from 'pinia';
import { useWatchdogStore } from './store/watchdog.store';
import {
  documentTypeApiService,
  userApiService,
  subOrgsApiService,
} from 'src/services';
import Loader from 'src/components/Loader.vue';
import GeneralTab from './components/GeneralTab.vue';
import ExportConfigurationsCard from './components/ExportConfigurationsCard.vue';
import WatchdogLogsCard from './components/WatchdogLogsCard.vue';
import XsltTemplatesTab from './components/XsltTemplatesTab.vue';
import WatchdogSetupDrawer from './components/WatchdogSetupDrawer.vue';
import type { WatchdogTab, DropdownOption } from './types/watchdog.types';
import { filterStoreDocTypes } from 'src/utils/docTypeFilter';

// ============================================
// ROUTER
// ============================================

const route = useRoute();
const router = useRouter();

// Valid tab names for URL persistence
const validTabs: WatchdogTab[] = ['general', 'configurations', 'status', 'xslt'];

// Get initial tab from URL or default to 'general'
function getInitialTab(): WatchdogTab {
  const urlTab = route.query.tab as string;
  if (urlTab && validTabs.includes(urlTab as WatchdogTab)) {
    return urlTab as WatchdogTab;
  }
  return 'general';
}

// ============================================
// STORE
// ============================================

const store = useWatchdogStore();
const { activeTab: storeActiveTab } = storeToRefs(store);

// ============================================
// LOCAL STATE
// ============================================

// Tab state - initialize from URL or store
const activeTab = ref<WatchdogTab>(getInitialTab());

// Setup drawer state
const showSetupDrawer = ref(false);
const setupApiKey = ref('');

// Data for configurations tab
const docTypes = ref<Array<{ key: string; title: string; selected?: boolean }>>([]);
const subOrgs = ref<DropdownOption[]>([]);

// ============================================
// WATCHERS
// ============================================

// Sync local tab state with store and URL
watch(activeTab, (newTab) => {
  store.setActiveTab(newTab);
  // Update URL without navigation (preserves history)
  router.replace({ query: { ...route.query, tab: newTab } });
});

// Sync store tab state with local (for external updates like jumpToConfiguration)
watch(storeActiveTab, (newTab) => {
  if (activeTab.value !== newTab) {
    activeTab.value = newTab;
  }
});

// ============================================
// METHODS
// ============================================

// Fetch API key for setup drawer
async function fetchSetupApiKey() {
  try {
    const data = { app_key: 'FELLOW_DOC2' };
    const response = await userApiService.getAppSubscription(data);
    if (response && response.length > 0) {
      setupApiKey.value = response[0].token;
    }
  } catch (error) {
    console.error('[WatchdogSettings] Failed to fetch API key:', error);
  }
}

// Fetch document types for configurations
async function fetchDocTypes() {
  try {
    const response = await documentTypeApiService.fetchDocTypes();
    if (response.data) {
      docTypes.value = filterStoreDocTypes(
        response.data.filter((doc_type: { is_active: boolean; document_name: string }) => doc_type.is_active),
      )
        .map((doc_type: { title: string; document_key: string; document_name: string }) => ({
          title: doc_type.title,
          key: doc_type.document_key,
          selected: false,
        }));
    }
  } catch (err) {
    console.error('[WatchdogSettings] Failed to fetch doc types:', err);
  }
}

// Fetch sub-organizations for configurations
async function fetchSubOrgs() {
  try {
    const response = await subOrgsApiService.getSubOrgsWithUsers();
    if (response) {
      subOrgs.value = [];
      for (const [, item] of Object.entries(response)) {
        const subOrg = item as { id: string; name: string };
        subOrgs.value.push({
          label: subOrg.name,
          value: subOrg.id,
        });
      }
    }
  } catch (err) {
    console.error('[WatchdogSettings] Failed to fetch sub-orgs:', err);
  }
}

// ============================================
// LIFECYCLE
// ============================================

onMounted(() => {
  fetchSetupApiKey();
  fetchDocTypes();
  fetchSubOrgs();

  // Deep links: auto-open panels/drawers via ?open= query param
  const openAction = route.query.open as string | undefined;
  if (openAction === 'xslt-templates') {
    activeTab.value = 'xslt';
  } else if (openAction === 'setup-drawer') {
    showSetupDrawer.value = true;
  } else if (openAction === 'bulk-copy' || openAction === 'load-import' || openAction === 'new-import') {
    // Switch to configurations tab so ExportConfigurationsCard mounts and handles its own deep-link
    activeTab.value = 'configurations';
  }
});
</script>

