<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, computed, onMounted, onBeforeUnmount } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { copyToClipboard } from 'quasar';
import { exportApiService, userApiService, watchdogApiService } from 'src/services';
import { getCurrentEnvironment } from 'src/pages/APIs';
import {
  WATCHDOG_SERVICE_INSTALL_COMMAND,
  WATCHDOG_SERVICE_START_COMMAND,
  buildWatchdogSetupCommand,
  isDownloadableBuildUrl,
  isRunnableSetupCommand,
  resolveWatchdogDownloadUrl,
} from '../watchdogSetup';
import WatchdogStatusCard from './WatchdogStatusCard.vue';

const { t } = useTranslate();

// ============================================
// STATE
// ============================================

// API Key and version
const setupApiKey = ref('');
const latestVersion = ref<string | null>(null);
const latestDownloadUrl = ref<string | null>(null);

// Update schedule state
const watchdogStatus = ref<{ online: boolean; auto_update_check_interval?: number } | null>(null);
const selectedSchedule = ref('hourly');
const scheduleInProgress = ref(false);
const statusPollInterval = ref<number | null>(null);

// ============================================
// COMPUTED
// ============================================

// Schedule interval constants (must match backend AutoUpdateScheduler)
const INTERVAL_STARTUP_ONLY = -1;
const INTERVAL_HOURLY = 3600;
const INTERVAL_DAILY = 86400;
const INTERVAL_WEEKLY = 604800;

const currentEnvironment = computed(() => getCurrentEnvironment());

const scheduleOptions = computed(() => [
  { label: t.value('startup_only'), value: 'startup' },
  { label: t.value('hourly'), value: 'hourly' },
  { label: t.value('daily'), value: 'daily' },
  { label: t.value('weekly'), value: 'weekly' },
]);

const currentScheduleLabel = computed(() => {
  const opt = scheduleOptions.value.find((o) => o.value === selectedSchedule.value);
  return opt?.label || t.value('hourly');
});

// WatchDog resolves the API host it talks to from the API key's prefix, so the
// key has to carry this environment's (and region's) prefix — otherwise every
// non-production installation silently points at production.
const configCommand = computed(() => buildWatchdogSetupCommand(setupApiKey.value));

// Service commands shown in the installation guide (fixed, not env-specific).
const serviceInstallCommand = WATCHDOG_SERVICE_INSTALL_COMMAND;
const serviceStartCommand = WATCHDOG_SERVICE_START_COMMAND;

// Builds are published per environment as WatchDog_<env>-<version>.exe, while
// the API reports the bare version — rebuilding the file name without the
// environment tag pointed at a build that exists for no environment.
const downloadUrl = computed(() =>
  resolveWatchdogDownloadUrl({
    version: latestVersion.value,
    downloadUrl: latestDownloadUrl.value,
  }),
);

// True once we know a concrete build to hand the customer.
const hasResolvedBuild = computed(() => isDownloadableBuildUrl(downloadUrl.value));

// ============================================
// METHODS
// ============================================

// Map interval to preset name
function intervalToPreset(interval: number): string {
  switch (interval) {
    case INTERVAL_STARTUP_ONLY: return 'startup';
    case INTERVAL_HOURLY: return 'hourly';
    case INTERVAL_DAILY: return 'daily';
    case INTERVAL_WEEKLY: return 'weekly';
    default: return 'hourly';
  }
}

// Map preset name to interval
function presetToInterval(preset: string): number {
  switch (preset) {
    case 'startup': return INTERVAL_STARTUP_ONLY;
    case 'hourly': return INTERVAL_HOURLY;
    case 'daily': return INTERVAL_DAILY;
    case 'weekly': return INTERVAL_WEEKLY;
    default: return INTERVAL_HOURLY;
  }
}

// Fetch API key for setup drawer
async function fetchSetupApiKey() {
  try {
    const data = { app_key: 'FELLOW_DOC2' };
    const response = await userApiService.getAppSubscription(data);
    if (response && response.length > 0) {
      setupApiKey.value = response[0].token;
    }
  } catch (error) {
    console.error('[GeneralTab] Failed to fetch API key:', error);
  }
}

// Fetch latest version from backend API (environment-specific)
async function fetchLatestVersion() {
  try {
    const release = await watchdogApiService.getLatestRelease();
    latestVersion.value = release.version;
    latestDownloadUrl.value = release.download_url || null;
  } catch (error) {
    console.error('[GeneralTab] Failed to fetch latest version:', error);
    latestVersion.value = 'N/A';
    latestDownloadUrl.value = null;
  }
}

// Copy download link to clipboard
function copyDownloadLink() {
  if (!hasResolvedBuild.value) {
    notify.warning(t.value('watchdog_version_loading'));
    return;
  }
  copyToClipboard(downloadUrl.value).then(() => {
    notify.success(t.value('watchdog_copy_success'));
  });
}

// Copy config command to clipboard
function copyConfigCommand() {
  if (!isRunnableSetupCommand(configCommand.value)) {
    notify.warning(t.value('watchdog_api_key_missing'));
    return;
  }
  copyToClipboard(configCommand.value).then(() => {
    notify.success(t.value('watchdog_copy_success'));
  });
}

// Download the newest build published for THIS environment. Falls back to the
// release listing only while no concrete build is known.
function openDownloadUrl() {
  window.open(downloadUrl.value, '_blank');
}

// Update schedule via API
async function updateSchedule(preset: string) {
  scheduleInProgress.value = true;

  try {
    const interval = presetToInterval(preset);
    const response = await exportApiService.createWatchdogCommand(
      'SET_UPDATE_SCHEDULE',
      { interval }
    );

    if (response.success) {
      notify.success(t.value('schedule_updated'));
    } else {
      notify.error(t.value('schedule_update_failed'), {
        detail: response.message || t.value('unknown_error'),
      });
    }
  } catch (err) {
    console.error('[GeneralTab] Schedule update failed:', err);
    notify.error(t.value('schedule_update_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  } finally {
    scheduleInProgress.value = false;
  }
}

// Fetch WatchDog status for schedule panel visibility
async function fetchWatchdogStatus() {
  try {
    const response = await exportApiService.getWatchdogStatus();
    if (response.success !== false) {
      watchdogStatus.value = response;
      // Update selected schedule from API response
      if (response.auto_update_check_interval !== undefined) {
        selectedSchedule.value = intervalToPreset(response.auto_update_check_interval);
      }
    }
  } catch (err) {
    console.error('[GeneralTab] Status fetch failed:', err);
    // Keep current status on error
  }
}

// ============================================
// LIFECYCLE
// ============================================

onMounted(() => {
  fetchSetupApiKey();
  fetchLatestVersion();
  fetchWatchdogStatus();

  // Poll status every 5 seconds
  statusPollInterval.value = window.setInterval(() => {
    fetchWatchdogStatus();
  }, 5000);
});

onBeforeUnmount(() => {
  if (statusPollInterval.value) {
    clearInterval(statusPollInterval.value);
    statusPollInterval.value = null;
  }
});
</script>

