<template>
  <div class="export-configurations-redesign anim-fade-in">
    <!-- Header Actions -->
    <div class="row items-center justify-between q-mb-md">
      <div class="header-left">
        <div class="text-h5 text-weight-bold text-primary">{{ $t('watchdog_configurations') }}</div>
        <div class="text-subtitle2 text-grey-7">{{ $t('manage_watchdog_paths_desc') }}</div>
      </div>
      <div class="header-right row q-gutter-md">
        <q-btn
          outline
          color="primary"
          no-caps
          @click="navigateToExportSettings"
          class="rounded-pill q-px-lg"
        >
          <q-icon name="open_in_new" size="18px" class="q-mr-sm" />
          {{ $t('new_export_configuration') }}
        </q-btn>
        <q-btn
          color="primary"
          unelevated
          no-caps
          class="rounded-pill q-px-md shadow-2 import-dropdown"
        >
          <q-icon name="add" size="20px" class="q-mr-sm" />
          {{ $t('new_import_configuration') }}
          <q-icon name="arrow_drop_down" size="20px" class="q-ml-xs" />
          <q-menu anchor="bottom middle" self="top middle" auto-close class="import-dropdown-menu">
            <q-list dense style="min-width: 0; width: max-content">
              <q-item clickable v-close-popup @click="showImportModal = true">
                <q-item-section side class="q-pr-xs">
                  <q-icon name="upload" size="18px" />
                </q-item-section>
                <q-item-section>{{ $t('load_import_configurations') }}</q-item-section>
              </q-item>
              <q-separator />
              <q-item clickable v-close-popup @click="openCreateImportModal">
                <q-item-section side class="q-pr-xs">
                  <q-icon name="add_circle_outline" size="18px" />
                </q-item-section>
                <q-item-section>{{ $t('new_import_configuration') }}</q-item-section>
              </q-item>
            </q-list>
          </q-menu>
        </q-btn>
      </div>
    </div>

    <!-- Stats Summary (Symmetry - 4 columns) -->
    <div class="row q-col-gutter-lg q-mb-md">
      <div class="col-12 col-sm-6 col-md-3">
        <q-card flat class="stat-mini-card bg-blue-1 text-blue-9">
          <q-card-section class="row items-center no-wrap">
            <div class="stat-icon-bg bg-blue-2 q-mr-md">
              <q-icon name="file_download" size="20px" />
            </div>
            <div>
              <div class="text-caption opacity-7 text-uppercase letter-spacing-1">{{ $t('imports') }}</div>
              <div class="text-h6 text-weight-bold">{{ importConfigsCount }}</div>
            </div>
          </q-card-section>
        </q-card>
      </div>
      <div class="col-12 col-sm-6 col-md-3">
        <q-card flat class="stat-mini-card bg-green-1 text-green-9">
          <q-card-section class="row items-center no-wrap">
            <div class="stat-icon-bg bg-green-2 q-mr-md">
              <q-icon name="file_upload" size="20px" />
            </div>
            <div>
              <div class="text-caption opacity-7 text-uppercase letter-spacing-1">{{ $t('exports') }}</div>
              <div class="text-h6 text-weight-bold">{{ exportConfigsCount }}</div>
            </div>
          </q-card-section>
        </q-card>
      </div>
      <div class="col-12 col-sm-6 col-md-3">
        <q-card flat class="stat-mini-card bg-amber-1 text-amber-9">
          <q-card-section class="row items-center no-wrap">
            <div class="stat-icon-bg bg-amber-2 q-mr-md">
              <q-icon name="check_circle_outline" size="20px" />
            </div>
            <div>
              <div class="text-caption opacity-7 text-uppercase letter-spacing-1">{{ $t('active') }}</div>
              <div class="text-h6 text-weight-bold">{{ activeConfigsCount }}</div>
            </div>
          </q-card-section>
        </q-card>
      </div>
      <div class="col-12 col-sm-6 col-md-3">
        <q-card flat class="stat-mini-card bg-purple-1 text-purple-9">
          <q-card-section class="row items-center no-wrap">
            <div class="stat-icon-bg bg-purple-2 q-mr-md">
              <q-icon name="code" size="20px" />
            </div>
            <div>
              <div class="text-caption opacity-7 text-uppercase letter-spacing-1">{{ $t('templates') }}</div>
              <div class="text-h6 text-weight-bold">{{ xsltTemplates.length }}</div>
            </div>
          </q-card-section>
        </q-card>
      </div>
    </div>

    <!-- Main Table Card -->
    <q-card flat class="modern-card overflow-hidden">
      <!-- Bulk Actions Overlay -->
      <q-slide-transition>
        <div v-if="selectedConfigs.length > 0" class="bulk-action-overlay bg-primary text-white q-px-lg q-py-sm row items-center">
          <div class="text-subtitle2">
            <q-icon name="check_box" class="q-mr-sm" />
            {{ t('configurations_selected', { count: selectedConfigs.length }) }}
          </div>
          <q-space />
          <q-btn
            flat
            dense
            no-caps
            icon="content_copy"
            :label="t('copy_to_sub_orgs')"
            class="q-mr-md"
            @click="showBulkCopyModal = true"
          />
          <q-btn
            flat
            dense
            no-caps
            :label="t('deselect')"
            @click="selectedConfigs = []"
          />
        </div>
      </q-slide-transition>

      <q-card-section class="q-pa-none">
        <DocBitsTable
          :rows="tableConfigurations"
          :columns="tableColumns"
          row-key="id"
          table-id="watchdog_configurations_table"
          :loading="loading"
          :features="{
            sorting: true,
            filtering: false,
            selection: true,
            bulkActions: false,
            rowActions: true,
            resizable: false,
            pagination: false,
            columnReorder: false,
            columnSettings: false,
            stickyFirstColumn: false,
            stickyLastColumn: true,
          }"
          :row-actions="rowActions"
          :pagination="tablePagination"
          v-model:selected="selectedConfigs"
          no-data-label="no_configurations"
          table-class="modern-configurations-table"
          flat-style
          @row-action="handleRowAction"
          @row-click="handleRowClick"
          @update:sorting="handleSort"
        >
          <!-- Config Name Column -->
          <template #body-cell-name="{ row }">
            <div class="column">
              <div class="row items-center no-wrap">
                <span class="text-weight-bold text-dark">{{ row.name }}</span>
              </div>
              <span v-if="row.is_default" class="text-caption text-grey-6 italic">
                {{ t('default_fallback') }}
              </span>
            </div>
          </template>

          <!-- Type Column -->
          <template #body-cell-config_type="{ row }">
            <q-badge
              :color="row.config_type === 'import' ? 'blue-1' : 'green-1'"
              :text-color="row.config_type === 'import' ? 'blue-9' : 'green-9'"
              class="type-badge q-px-sm q-py-xs"
            >
              <q-icon
                :name="row.config_type === 'import' ? 'arrow_downward' : 'arrow_upward'"
                size="12px"
                class="q-mr-xs"
              />
              {{ row.config_type === 'import' ? t('import') : t('export') }}
            </q-badge>
          </template>

          <!-- Status Column -->
          <template #body-cell-is_active="{ row }">
            <div class="status-dot-container">
              <div class="status-dot" :class="row.is_active ? 'active' : 'inactive'"></div>
              <span class="text-caption text-grey-8">{{ row.is_active ? t('active') : t('inactive') }}</span>
            </div>
          </template>

          <!-- Path / Destination Column -->
          <template #body-cell-folder_path="{ row }">
            <div class="path-display-cell">
              <!-- Import -->
              <div v-if="row.config_type === 'import'" class="row items-center no-wrap">
                <q-icon name="folder_open" color="blue-grey-4" size="16px" class="q-mr-xs" />
                <span class="text-mono ellipsify">{{ row.import_path }}</span>
              </div>

              <!-- Export from Export Settings (on-premise) -->
              <div v-else-if="row.is_from_export_settings" class="row items-center no-wrap">
                <q-icon name="cloud_off" color="purple-5" size="16px" class="q-mr-xs" />
                <span class="text-purple-9 text-weight-medium">{{ getExportMethodLabel(row.export_method) }}</span>
              </div>

              <!-- Export Mapping -->
              <div v-else class="row items-center no-wrap">
                <template v-if="row.export_type === 'file'">
                  <q-icon name="drive_file_move" color="green-4" size="16px" class="q-mr-xs" />
                  <span class="text-mono ellipsify">{{ row.export_path }}</span>
                </template>
                <template v-else-if="row.export_type === 'standard'">
                  <q-icon name="settings" color="blue-7" size="16px" class="q-mr-xs" />
                  <span class="text-blue-9 text-weight-medium">{{ row.export_config_name || t('standard_export') }}</span>
                </template>
              </div>
            </div>
          </template>
        </DocBitsTable>
      </q-card-section>
    </q-card>

    <!-- Modal Components - Import configurations only -->
    <ConfigurationModal
      v-model="showConfigModal"
      :mode="configModalMode"
      :configuration="selectedConfiguration"
      :doc-types="docTypes"
      :sub-orgs="subOrgs"
      :existing-configurations="store.configurations"
      @save="handleConfigSave"
    />

    <BulkCopyModal
      v-model:show="showBulkCopyModal"
      :source-configs="selectedConfigs"
      @completed="handleBulkCopyCompleted"
    />

    <ImportConfigModal
      v-model:show="showImportModal"
      @completed="loadConfigurations"
    />

    <q-dialog v-model="showDeleteDialog" persistent transition-show="scale" transition-hide="scale">
      <q-card class="delete-dialog modern-card">
        <q-card-section class="bg-negative text-white q-pa-lg">
          <div class="row items-center">
            <q-icon name="warning" size="32px" class="q-mr-md" />
            <div class="text-h6">{{ t('delete_configuration') }}</div>
          </div>
        </q-card-section>
        <q-card-section class="q-pa-xl text-center">
          <p class="text-subtitle1">{{ t('delete_configuration_warning', { name: configToDelete?.name }) }}</p>
          <p class="text-grey-7">{{ t('irreversible_action') }}</p>
        </q-card-section>
        <q-card-actions align="right" class="q-pa-md">
          <q-btn flat :label="t('cancel')" color="grey-7" v-close-popup />
          <q-btn
            unelevated
            color="negative"
            :label="t('confirm_delete')"
            @click="executeDelete"
            :loading="deleteInProgress"
            class="rounded-pill q-px-lg"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, computed, onMounted, reactive, watch } from 'vue';
import { useRouter, useRoute } from 'vue-router';
import { useTranslate } from '@tolgee/vue';
import { useWatchdogStore } from '../store/watchdog.store';
import { exportApiService } from 'src/services';
import type {
  WatchdogConfiguration,
  WatchdogConfigurationInput,
  XsltTemplateInput,
  DropdownOption,
  ConfigModalMode,
  ExportConfigurationOption,
} from '../types/watchdog.types';

// Export methods that use WatchDog (on-premise connectivity)
const WATCHDOG_EXPORT_METHODS = [
  'watcher',
  'infor-idm-onpremise',
  'infor-bod-onpremise',
  'infor-ion-onpremise',
  'generic-api-onpremise',
];

// Extended configuration type that includes flag for export settings entries
interface DisplayConfiguration extends WatchdogConfiguration {
  /** Flag indicating this entry comes from Export Settings, not WatchDog API */
  is_from_export_settings?: boolean;
  /** Original export method from Export Settings */
  export_method?: string;
}
import ConfigurationModal from './ConfigurationModal.vue';
import BulkCopyModal from './BulkCopyModal.vue';
import ImportConfigModal from './ImportConfigModal.vue';
import { DocBitsTable } from 'src/components/Table';
import type {
  UnifiedTableColumn,
  RowActionItem,
  RowActionPayload,
  SortEventPayload,
} from 'src/components/Table';

const { t } = useTranslate();
const router = useRouter();
const route = useRoute();
const store = useWatchdogStore();

// Props
export interface ExportConfigurationsCardProps {
  docTypes: Array<{ key: string; title: string; selected?: boolean }>;
  subOrgs?: DropdownOption[];
}

const props = withDefaults(defineProps<ExportConfigurationsCardProps>(), {
  docTypes: () => [],
  subOrgs: () => [],
});

// State
const loading = ref(false);

// Modal state
const showConfigModal = ref(false);
const configModalMode = ref<ConfigModalMode>('create');
const selectedConfiguration = ref<WatchdogConfiguration | null>(null);;
const showBulkCopyModal = ref(false);
const showImportModal = ref(false);

// Deep link: auto-open modals via ?open= query param
function checkDeepLink() {
  const action = route.query.open;
  if (action === 'load-import') {
    showImportModal.value = true;
  } else if (action === 'new-import') {
    openCreateImportModal();
  } else if (action === 'bulk-copy') {
    showBulkCopyModal.value = true;
  }
}
onMounted(() => { checkDeepLink(); });
watch(() => route.query.open, () => { checkDeepLink(); });

// Row selection state
const selectedConfigs = ref<WatchdogConfiguration[]>([]);

// Delete dialog state
const showDeleteDialog = ref(false);
const configToDelete = ref<WatchdogConfiguration | null>(null);
const deleteInProgress = ref(false);

// Export configurations from Settings > Export (for Infor export linking)
const exportConfigurations = ref<ExportConfigurationOption[]>([]);

// Table columns definition for DocBitsTable
const tableColumns = computed<UnifiedTableColumn[]>(() => [
  {
    name: 'name',
    label: t.value('config_name'),
    field: 'name',
    align: 'left',
    sortable: true,
  },
  {
    name: 'config_type',
    label: t.value('type'),
    field: 'config_type',
    align: 'left',
    sortable: true,
  },
  {
    name: 'is_active',
    label: t.value('status'),
    field: 'is_active',
    align: 'center',
    sortable: true,
  },
  {
    name: 'sub_org_name',
    label: t.value('sub_organization'),
    field: 'sub_org_name',
    align: 'left',
    sortable: true,
  },
  {
    name: 'doc_type_name',
    label: t.value('document_type'),
    field: 'doc_type_name',
    align: 'left',
    sortable: true,
  },
  {
    name: 'folder_path',
    label: t.value('details'),
    field: 'folder_path',
    align: 'left',
    sortable: false,
  }
]);

// Sort state for DocBitsTable
const tablePagination = reactive({
  sortBy: 'name' as string | null,
  descending: false,
  page: 1,
  rowsPerPage: 0,
  rowsNumber: 0,
});

// Handle sorting changes
const handleSort = (payload: SortEventPayload) => {
  tablePagination.sortBy = payload.column;
  tablePagination.descending = payload.direction === 'desc';
};

// Row actions for DocBitsTable - different actions for import vs export configs
const rowActions = computed<RowActionItem[]>(() => [
  {
    key: 'edit',
    label: 'edit',
    icon: 'edit',
    color: 'primary',
    // Only show edit action for import configs (exports redirect to export settings)
    show: (row: DisplayConfiguration) => row.config_type === 'import' && !row.is_from_export_settings,
  },
  {
    key: 'edit_in_export',
    label: 'edit',
    icon: 'edit',
    color: 'primary',
    // Show for export configs (both WatchDog and from Export Settings)
    show: (row: DisplayConfiguration) => row.config_type === 'export',
  },
  {
    key: 'copy',
    label: 'copy',
    icon: 'content_copy',
    color: 'grey-7',
    // Only allow copying import configs (not from export settings)
    show: (row: DisplayConfiguration) => row.config_type === 'import' && !row.is_from_export_settings,
  },
  {
    key: 'delete',
    label: 'delete',
    icon: 'delete',
    color: 'negative',
    separator: true,
    // Don't allow delete for default or export settings entries
    show: (row: DisplayConfiguration) => !row.is_default,
  },
]);

// Computed
const sortedConfigurations = computed(() => store.sortedConfigurations);
const xsltTemplates = computed(() => store.xsltTemplates);

// Helper function to resolve doc_type_name from doc_type_key
const resolveDocTypeName = (docTypeKey: string | null | undefined): string => {
  if (!docTypeKey) return '-';
  const docType = props.docTypes.find(d => d.key === docTypeKey);
  return docType?.title || docTypeKey;
};

// Helper function to resolve sub_org_name from sub_org_id
const resolveSubOrgName = (subOrgId: string | null | undefined): string => {
  if (!subOrgId) return '-';
  const subOrg = props.subOrgs.find(s => s.value === subOrgId);
  return subOrg?.label || subOrgId;
};

// Map export configurations from Export Settings to display format
const watchdogRelatedExports = computed<DisplayConfiguration[]>(() => {
  return exportConfigurations.value
    .filter(c => WATCHDOG_EXPORT_METHODS.includes(c.export_method))
    .map(c => ({
      id: `export-${c.id}`,  // Prefix to distinguish from WatchDog configs
      name: c.title,
      config_type: 'export' as const,
      is_active: c.is_active ?? true,
      sub_org_id: c.sub_org_id || null,
      sub_org_name: resolveSubOrgName(c.sub_org_id),
      doc_type_key: c.doc_type || null,
      doc_type_name: resolveDocTypeName(c.doc_type),
      import_path: null,
      success_path: null,
      export_path: null,
      xslt_template_id: null,
      xslt_template_name: undefined,
      export_type: 'standard' as const,
      export_config_id: c.id,
      export_config_name: c.title,
      is_default: false,
      is_from_export_settings: true,
      export_method: c.export_method,
    }));
});

// Merge WatchDog configs with WatchDog-related exports from Export Settings
const mergedConfigurations = computed<DisplayConfiguration[]>(() => {
  // Get WatchDog store configs and resolve names if not provided by backend
  const storeConfigs: DisplayConfiguration[] = store.sortedConfigurations.map(c => ({
    ...c,
    is_from_export_settings: false,
    // Resolve names from IDs if not already provided by backend
    sub_org_name: c.sub_org_name || resolveSubOrgName(c.sub_org_id),
    doc_type_name: c.doc_type_name || resolveDocTypeName(c.doc_type_key),
  }));

  // Combine with exports from Export Settings
  return [...storeConfigs, ...watchdogRelatedExports.value];
});

const importConfigsCount = computed(() =>
  mergedConfigurations.value.filter(c => c.config_type === 'import').length
);
const exportConfigsCount = computed(() =>
  mergedConfigurations.value.filter(c => c.config_type === 'export').length
);
const activeConfigsCount = computed(() =>
  mergedConfigurations.value.filter(c => c.is_active).length
);

// All configurations for table display (exclude default config)
const tableConfigurations = computed(() =>
  mergedConfigurations.value.filter(c => !c.is_default)
);

// Selectable configurations for bulk operations (exclude export settings entries)
const selectableConfigurations = computed(() =>
  mergedConfigurations.value.filter(c => !c.is_default && !c.is_from_export_settings)
);

// Methods
const openCreateImportModal = () => {
  configModalMode.value = 'create';
  selectedConfiguration.value = null;
  showConfigModal.value = true;
};

const navigateToExportSettings = () => {
  // Navigate to export settings page to create a new watcher export
  router.push('/settings/export/new?type=watcher');
};

const navigateToEditExport = (config: DisplayConfiguration) => {
  // For configs from Export Settings, extract the real ID (remove 'export-' prefix)
  let exportId: string | number;
  if (config.is_from_export_settings && config.export_config_id) {
    exportId = config.export_config_id;
  } else if (typeof config.id === 'string' && config.id.startsWith('export-')) {
    exportId = config.id.replace('export-', '');
  } else {
    exportId = config.id;
  }
  // Navigate to export settings page to edit this export
  router.push(`/settings/export/${exportId}`);
};

const openEditModal = (config: DisplayConfiguration) => {
  // For export configs (both WatchDog and from Export Settings), redirect to export settings
  if (config.config_type === 'export') {
    navigateToEditExport(config);
    return;
  }
  // For import configs, open the modal (only WatchDog configs, not from Export Settings)
  if (config.is_from_export_settings) {
    return;
  }
  configModalMode.value = 'edit';
  selectedConfiguration.value = config;
  showConfigModal.value = true;
};

const copyConfiguration = (config: DisplayConfiguration) => {
  // Only allow copying import configurations (exports are managed in export settings)
  // Also don't allow copying configs from Export Settings
  if (config.config_type === 'export' || config.is_from_export_settings) {
    return;
  }
  configModalMode.value = 'copy';
  selectedConfiguration.value = config;
  showConfigModal.value = true;
};

const confirmDelete = (config: DisplayConfiguration) => {
  configToDelete.value = config;
  showDeleteDialog.value = true;
};

// Handle row actions from DocBitsTable
const handleRowAction = (payload: RowActionPayload) => {
  const row = payload.row as DisplayConfiguration;
  if (payload.action === 'edit') {
    openEditModal(row);
  } else if (payload.action === 'edit_in_export') {
    navigateToEditExport(row);
  } else if (payload.action === 'copy') {
    copyConfiguration(row);
  } else if (payload.action === 'delete') {
    confirmDelete(row);
  }
};

// Handle row click
const handleRowClick = (payload: { row: DisplayConfiguration }) => {
  openEditModal(payload.row);
};

const executeDelete = async () => {
  if (!configToDelete.value) return;
  console.log('Deleting configuration:', configToDelete.value);
  deleteInProgress.value = true;
  try {
    if (configToDelete.value.config_type === 'export') {
      await exportApiService.deleteRecord(String(configToDelete.value.export_config_id));
    } else {
      // This is an export configuration from Export Settings - call export API to delete
      await store.deleteConfiguration(configToDelete.value.id);
    }
    notify.success(t.value('configuration_deleted'));
    showDeleteDialog.value = false;
    configToDelete.value = null;
    loadExportConfigurations(); // Refresh export configurations after deletion
  } catch (err) {
    notify.error(t.value('configuration_delete_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  } finally {
    deleteInProgress.value = false;
  }
};

const handleConfigSave = async (input: WatchdogConfigurationInput) => {
  try {
    loading.value = true;
    if (configModalMode.value === 'create' || configModalMode.value === 'copy') {
      await store.createConfiguration(input);
      notify.success(t.value('configuration_created'));
    } else {
      if (selectedConfiguration.value) {
        await store.updateConfiguration(selectedConfiguration.value.id, input);
        notify.success(t.value('configuration_updated'));
      }
    }
    showConfigModal.value = false;
  } catch (err) {
    notify.error(t.value('configuration_save_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  } finally {
    loading.value = false;
  }
};

// XSLT Template handlers
const handleTemplateCreate = async (input: XsltTemplateInput) => {
  try {
    await store.createXsltTemplate(input);
    notify.success(t.value('template_created'));
  } catch (err) {
    notify.error(t.value('template_create_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  }
};

const handleTemplateUpdate = async (id: string, input: Partial<XsltTemplateInput>) => {
  try {
    await store.updateXsltTemplate(id, input);
    notify.success(t.value('template_updated'));
  } catch (err) {
    notify.error(t.value('template_update_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  }
};

const handleTemplateDelete = async (id: string) => {
  try {
    await store.deleteXsltTemplate(id);
    notify.success(t.value('template_deleted'));
  } catch (err) {
    notify.error(t.value('template_delete_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  }
};

// Bulk copy handler
const handleBulkCopyCompleted = () => {
  selectedConfigs.value = [];
  notify.success(t.value('bulk_copy_completed'));
};

// Get human-readable label for export method
const getExportMethodLabel = (method: string | undefined): string => {
  if (!method) return t.value('unknown_export');
  const labels: Record<string, string> = {
    'watcher': t.value('watcher_xslt_export'),
    'infor-idm-onpremise': t.value('infor_idm_onpremise'),
    'infor-bod-onpremise': t.value('infor_bod_onpremise'),
    'infor-ion-onpremise': t.value('infor_ion_onpremise'),
  };
  return labels[method] || method;
};

// Get short label for export method (used in badges)
const getExportMethodShortLabel = (method: string | undefined): string => {
  if (!method) return t.value('unknown_export');
  const labels: Record<string, string> = {
    'watcher': t.value('watcher_short'),
    'infor-idm-onpremise': t.value('idm_onprem_short'),
    'infor-bod-onpremise': t.value('bod_onprem_short'),
    'infor-ion-onpremise': t.value('ion_onprem_short'),
  };
  return labels[method] || method;
};

// Load configurations (called after import)
const loadConfigurations = async () => {
  loading.value = true;
  try {
    await store.loadConfigurations();
  } finally {
    loading.value = false;
  }
};

// Load export configurations from Settings > Export
const loadExportConfigurations = async () => {
  try {
    const response = await exportApiService.getAll();
    if (response.data) {
      exportConfigurations.value = response.data.map((config: any) => ({
        id: config.id,
        title: config.title,
        export_method: config.export_method,
        doc_type: config.doc_type,
        sub_org_id: config.sub_org_id || null,
        is_active: config.is_active,
        execution_order: config.execution_order,
      }));
    }
  } catch (err) {
    console.error('Failed to load export configurations:', err);
  }
};

// Initialize data on mount
onMounted(async () => {
  loading.value = true;
  try {
    await Promise.all([
      store.loadConfigurations(),
      store.loadXsltTemplates(),
      loadExportConfigurations(),
    ]);
  } finally {
    loading.value = false;
  }
});

// Watch for target config ID to open edit modal when jumping from XSLT templates
watch(
  () => store.targetConfigId,
  (newId) => {
    if (newId) {
      const config = store.configurations.find((c) => c.id === newId);
      if (config) {
        configModalMode.value = 'edit';
        selectedConfiguration.value = config;
        showConfigModal.value = true;
      }
      store.clearTargetConfig();
    }
  },
  { immediate: true }
);

</script>

