  <div class="xslt-templates-redesign anim-fade-in">
    <!-- Header with Symmetry (Hidden if embedded) -->
    <div v-if="!embedded" class="row items-center justify-between q-mb-md">
      <div class="header-left">
        <div class="text-h5 text-weight-bold text-primary">{{ $t('xslt_templates') }}</div>
        <div class="text-subtitle2 text-grey-7">{{ $t('xslt_templates_desc') }}</div>
      </div>
      <div class="header-right">
        <q-btn
          color="primary"
          unelevated
          no-caps
          @click="createNewTemplate"
          class="rounded-pill q-px-lg shadow-2"
        >
          <q-icon name="add" size="20px" class="q-mr-sm" />
          {{ $t('new_template') }}
        </q-btn>
      </div>
    </div>

    <!-- Header for embedded view -->
    <div v-else class="row items-center justify-between q-mb-lg">
      <div class="text-h6 text-weight-bold text-dark">{{ $t('xslt_templates') }}</div>
      <q-btn
        flat
        color="primary"
        no-caps
        @click="createNewTemplate"
        icon="add"
        :label="$t('new_template')"
      />
    </div>

    <!-- Stats Summary (Symmetry - 4 columns to match Configurations tab) -->
    <div class="row q-col-gutter-lg q-mb-md">
      <div class="col-12 col-sm-6 col-md-3">
        <q-card flat class="stat-mini-card bg-purple-1 text-purple-9">
          <q-card-section class="row items-center no-wrap">
            <div class="stat-icon-bg bg-purple-2 q-mr-md">
              <q-icon name="code" size="20px" />
            </div>
            <div>
              <div class="text-caption opacity-7 text-uppercase letter-spacing-1">{{ $t('total_templates') }}</div>
              <div class="text-h6 text-weight-bold">{{ sortedTemplates.length }}</div>
            </div>
          </q-card-section>
        </q-card>
      </div>
      <div class="col-12 col-sm-6 col-md-3">
        <q-card flat class="stat-mini-card bg-blue-1 text-blue-9">
          <q-card-section class="row items-center no-wrap">
            <div class="stat-icon-bg bg-blue-2 q-mr-md">
              <q-icon name="link" size="20px" />
            </div>
            <div>
              <div class="text-caption opacity-7 text-uppercase letter-spacing-1">{{ $t('in_use') }}</div>
              <div class="text-h6 text-weight-bold">{{ usedTemplatesCount }}</div>
            </div>
          </q-card-section>
        </q-card>
      </div>
      <div class="col-12 col-sm-6 col-md-3">
        <q-card flat class="stat-mini-card bg-green-1 text-green-9">
          <q-card-section class="row items-center no-wrap">
            <div class="stat-icon-bg bg-green-2 q-mr-md">
              <q-icon name="terminal" size="20px" />
            </div>
            <div>
              <div class="text-caption opacity-7 text-uppercase letter-spacing-1">{{ $t('scripts_active') }}</div>
              <div class="text-h6 text-weight-bold">{{ activeScriptsCount }}</div>
            </div>
          </q-card-section>
        </q-card>
      </div>
      <div class="col-12 col-sm-6 col-md-3">
        <q-card flat class="stat-mini-card bg-amber-1 text-amber-9">
          <q-card-section class="row items-center no-wrap">
            <div class="stat-icon-bg bg-amber-2 q-mr-md">
              <q-icon name="history" size="20px" />
            </div>
            <div>
              <div class="text-caption opacity-7 text-uppercase letter-spacing-1">{{ $t('recent_updates') }}</div>
              <div class="text-h6 text-weight-bold">{{ recentTemplatesCount }}</div>
            </div>
          </q-card-section>
        </q-card>
      </div>
    </div>

    <!-- Main Table Card -->
    <q-card flat class="modern-card overflow-hidden">
      <q-card-section class="q-pa-none">
        <DocBitsTable
          :rows="sortedTemplates"
          :columns="tableColumns"
          row-key="id"
          table-id="xslt_templates_table"
          :loading="loading"
          :features="{
            sorting: true,
            filtering: false,
            selection: true,
            bulkActions: false,
            rowActions: true,
            resizable: false,
            pagination: false,
            columnReorder: false,
            columnSettings: false,
            stickyFirstColumn: false,
            stickyLastColumn: true,
          }"
          :row-actions="rowActions"
          v-model:selected="selectedTemplates"
          no-data-label="no_templates"
          table-class="modern-xslt-table"
          flat-style
          @row-action="handleRowAction"
          @row-click="handleRowClick"
        >
          <!-- Name Column -->
          <template #body-cell-name="{ row }">
            <div class="row items-center no-wrap">
              <q-icon name="description" color="amber-8" size="20px" class="q-mr-sm" />
              <span class="text-weight-bold text-dark">{{ row.name }}</span>
            </div>
          </template>

          <!-- Usage Column -->
          <template #body-cell-usage_count="{ row }">
            <div v-if="row.used_by_configs?.length === 0" class="text-grey-6 text-caption">
              {{ t('not_used') }}
            </div>
            <div v-else class="config-links">
              <span
                v-for="(cfg, idx) in row.used_by_configs as ConfigUsageInfo[]"
                :key="cfg.id"
              >
                <a
                  class="text-primary cursor-pointer config-link"
                  @click.stop="goToConfig(cfg.id)"
                >{{ cfg.name }}</a><span v-if="idx < row.used_by_configs.length - 1">, </span>
              </span>
            </div>
          </template>
        </DocBitsTable>
      </q-card-section>
    </q-card>

    <!-- Template Edit Modal -->
    <XsltTemplatesModal
      v-model="showModal"
      :templates="sortedTemplates"
      :initial-template-id="targetTemplateId"
      @create="handleCreate"
      @update="handleUpdate"
      @delete="handleDelete"
      @selection-handled="store.clearTargetXslt()"
    />

    <!-- Delete Confirmation Dialog -->
    <q-dialog v-model="showDeleteDialog" persistent transition-show="scale" transition-hide="scale">
      <q-card class="modern-card" style="width: 400px">
        <q-card-section class="bg-negative text-white q-pa-lg">
          <div class="text-h6">{{ t('delete_template') }}</div>
        </q-card-section>
        <q-card-section class="q-pa-xl text-center">
          <p class="text-subtitle1">{{ t('delete_template_warning', { name: templateToDelete?.name }) }}</p>
        </q-card-section>
        <q-card-actions align="right" class="q-pa-md">
          <q-btn flat :label="t('cancel')" color="grey-7" v-close-popup />
          <q-btn
            unelevated
            color="negative"
            :label="t('delete')"
            @click="executeDelete"
            :loading="deleting"
            class="rounded-pill q-px-lg"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, computed, onMounted, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { useWatchdogStore } from '../store/watchdog.store';
import type {
  XsltTemplate,
  XsltTemplateInput,
  ConfigUsageInfo,
} from '../types/watchdog.types';
import { useRouter } from 'vue-router';
import XsltTemplatesModal from './XsltTemplatesModal.vue';
import { DocBitsTable } from 'src/components/Table';
import type { UnifiedTableColumn, RowActionItem, RowActionPayload } from 'src/components/Table';

const { t } = useTranslate();
const store = useWatchdogStore();
const router = useRouter();

// Props
interface Props {
  embedded?: boolean;
}

const props = withDefaults(defineProps<Props>(), {
  embedded: false,
});

// State
const loading = ref(false);
const showModal = ref(false);
const showDeleteDialog = ref(false);
const templateToDelete = ref<XsltTemplate | null>(null);
const deleting = ref(false);
const selectedTemplates = ref<XsltTemplate[]>([]);

// Computed
const sortedTemplates = computed(() => store.sortedTemplates);
const targetTemplateId = computed(() => store.targetXsltId);

const usedTemplatesCount = computed(() => 
  store.xsltTemplates.filter(t => t.usage_count > 0).length
);

const activeScriptsCount = computed(() => 
  store.configurations.filter(c => c.is_active).length
);

const recentTemplatesCount = computed(() => {
  const oneWeekAgo = new Date();
  oneWeekAgo.setDate(oneWeekAgo.getDate() - 7);
  return store.xsltTemplates.filter(t => t.updated_at && new Date(t.updated_at) > oneWeekAgo).length;
});

// Table Columns
const tableColumns = computed<UnifiedTableColumn[]>(() => [
  { name: 'name', label: t.value('template_name'), field: 'name', align: 'left', sortable: true },
  { name: 'usage_count', label: t.value('export_configuration'), field: 'usage_count', align: 'center', sortable: true },
]);

// Row Actions
const rowActions = computed<RowActionItem[]>(() => [
  { key: 'edit', label: 'edit', icon: 'edit', color: 'primary' },
  { key: 'copy', label: 'duplicate', icon: 'content_copy', color: 'grey-7' },
  { 
    key: 'delete', 
    label: 'delete', 
    icon: 'delete', 
    color: 'negative', 
    separator: true,
    show: (row: XsltTemplate) => row.usage_count === 0
  },
]);

// Watch for target template ID from jump action
watch(() => store.targetXsltId, (newId) => {
  if (newId) {
    showModal.value = true;
  }
}, { immediate: true });

// Methods
const createNewTemplate = () => {
  store.clearTargetXslt();
  showModal.value = true;
};

const editTemplate = (template: XsltTemplate) => {
  store.jumpToXslt(template.id);
  showModal.value = true;
};

const goToConfig = (configId: string) => {
  // Switch to configurations tab and jump to the specific config
  store.jumpToConfiguration(configId);
  // The watchdog page will handle tab switching when jumpToConfiguration is called
};

const handleRowClick = (payload: { row: XsltTemplate }) => {
  editTemplate(payload.row);
};

const handleRowAction = (payload: RowActionPayload) => {
  const row = payload.row as XsltTemplate;
  if (payload.action === 'edit') editTemplate(row);
  else if (payload.action === 'copy') duplicateTemplate(row);
  else if (payload.action === 'delete') confirmDelete(row);
};

const duplicateTemplate = async (template: XsltTemplate) => {
  try {
    await store.createXsltTemplate({
      name: `${template.name} (Copy)`,
      content: template.content,
    });
    notify.success(t.value('template_duplicated'));
  } catch (err) {
    notify.error(t.value('template_duplicate_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  }
};

const confirmDelete = (template: XsltTemplate) => {
  if (template.usage_count > 0) return;
  templateToDelete.value = template;
  showDeleteDialog.value = true;
};

const executeDelete = async () => {
  if (!templateToDelete.value) return;

  deleting.value = true;
  try {
    await store.deleteXsltTemplate(templateToDelete.value.id);
    notify.success(t.value('template_deleted'));
    showDeleteDialog.value = false;
    templateToDelete.value = null;
  } catch (err) {
    notify.error(t.value('template_delete_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  } finally {
    deleting.value = false;
  }
};

// Modal handlers
const handleCreate = async (input: XsltTemplateInput) => {
  try {
    await store.createXsltTemplate(input);
    notify.success(t.value('template_created'));
  } catch (err) {
    notify.error(t.value('template_create_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  }
};

const handleUpdate = async (id: string, input: Partial<XsltTemplateInput>) => {
  try {
    await store.updateXsltTemplate(id, input);
    notify.success(t.value('template_updated'));
  } catch (err) {
    notify.error(t.value('template_update_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  }
};

const handleDelete = async (id: string) => {
  try {
    await store.deleteXsltTemplate(id);
    notify.success(t.value('template_deleted'));
  } catch (err) {
    notify.error(t.value('template_delete_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
    });
  }
};

// Load templates on mount
onMounted(async () => {
  loading.value = true;
  try {
    await store.loadXsltTemplates();
  } finally {
    loading.value = false;
  }
});
</script>

