<template>
  <div>
  <q-card flat class="watchdog-hero-status modern-card overflow-hidden">
    <!-- Header styled like expansion panel -->
    <div class="status-header highlighted-back row items-center q-pa-lg">
      <div class="status-icon-container bg-white shadow-1 q-mr-lg">
        <q-icon
          size="28px"
          :name="statusIcon"
          :color="statusColor"
        />
      </div>
      
      <div class="column">
        <span class="text-h6 text-weight-bold">{{ t('watchdog_status') }}</span>
        <div class="row items-center">
          <div class="status-indicator-dot q-mr-xs" :class="isOnline ? 'bg-positive' : 'bg-negative'"></div>
          <span class="text-caption text-weight-medium" :class="'text-' + statusColor">
            {{ statusLabel.toUpperCase() }}
          </span>
        </div>
      </div>

      <q-space />

      <div class="row items-center q-gutter-md">
        <div v-if="hasPendingCommands" class="pending-badge row items-center q-px-md q-py-xs">
          <q-spinner-dots color="primary" size="16px" class="q-mr-sm" />
          <span class="text-primary text-caption text-weight-bold text-uppercase">
            {{ t('command_pending') }}
          </span>
          <q-tooltip>{{ t('command_pending_tooltip') }}</q-tooltip>
        </div>

        <f-btn
          v-if="hasUpdate && isOnline && !loading"
          appearance="warning"
          :label="updateInProgress ? t('updating') : t('update_now')"
          icon="system_update"
          size="sm"
          class="rounded-pill"
          :blocked="isUpdateDisabled"
          :loading="updateInProgress"
          @click="showUpdateDialog = true"
        />
        
        <f-btn
          v-if="!loading"
          appearance="negative-tertiary"
          :label="t('restart')"
          icon="refresh"
          size="sm"
          class="rounded-pill"
          :blocked="isRestartDisabled"
          @click="showRestartDialog = true"
        />
      </div>
    </div>

    <q-separator class="opacity-5" />

    <!-- Content section -->
    <q-card-section class="q-pa-xl">
      <div v-if="loading" class="row items-center justify-center q-pa-xl">
        <q-spinner-dots color="primary" size="40px" />
      </div>

      <div v-else class="row q-col-gutter-xl">
        <!-- Core Stats -->
        <div class="col-12 col-md-4 border-right-divider">
          <div class="section-label q-mb-md">{{ t('activity_tracking') }}</div>
          
          <div class="info-row q-mb-md">
            <div class="text-caption text-grey-6">{{ t('last_seen') }}</div>
            <div class="text-subtitle1 text-weight-bold">
              {{ formattedLastSeen }}
              <q-tooltip v-if="lastSeen">{{ exactTimestamp }}</q-tooltip>
            </div>
          </div>

          <div class="info-row">
            <div class="text-caption text-grey-6">{{ t('last_restart') }}</div>
            <div class="text-subtitle1 text-weight-bold">{{ formattedLastRestart }}</div>
          </div>
        </div>

        <!-- Version & Updates -->
        <div class="col-12 col-md-4 border-right-divider">
          <div class="section-label q-mb-md">{{ t('software_version') }}</div>
          
          <div class="info-row q-mb-md row items-center">
            <div class="column">
              <div class="text-caption text-grey-6">{{ t('current_version') }}</div>
              <div class="text-subtitle1 text-weight-bold">
                {{ displayVersion || '---' }}
                <span v-if="displayInstallDate" class="text-caption text-weight-regular text-grey-6 q-ml-xs">
                  ({{ t('installed') }} {{ displayInstallDate }})
                </span>
              </div>
            </div>
            <q-badge v-if="hasUpdate" color="warning" class="q-ml-md q-py-xs q-px-sm">
              {{ t('new_update_available') }}
            </q-badge>
          </div>

          <div class="info-row" v-if="isOnline">
            <div class="text-caption text-grey-6 q-mb-xs">{{ t('auto_update') }}</div>
            <f-toggle
              :model-value="autoUpdateEnabled"
              :label="autoUpdateEnabled ? t('enabled') : t('disabled')"
              :disable="!isOnline || hasPendingCommands"
              size="sm"
              @update:model-value="showAutoUpdateDialog = true"
            />
          </div>
        </div>

        <!-- System Resources -->
        <div class="col-12 col-md-4">
          <div class="section-label q-mb-md">{{ t('system_resources') }}</div>
          
          <div class="row q-col-gutter-md">
            <div class="col-6">
              <div class="text-caption text-grey-6">{{ t('free_ram') }}</div>
              <div class="text-subtitle1 text-weight-bold">{{ freeRam }}</div>
            </div>
            <div class="col-6">
              <div class="text-caption text-grey-6">{{ t('free_disk') }}</div>
              <div class="text-subtitle1 text-weight-bold">{{ freeDisk }}</div>
            </div>
            <div class="col-12 q-mt-sm">
              <div class="text-caption text-grey-6">{{ t('installation_path') }}</div>
              <div class="text-mono-path bg-grey-1 q-pa-sm rounded-borders row items-center no-wrap">
                <span class="ellipsify">{{ installationPath || '---' }}</span>
                <q-btn flat dense round size="xs" icon="content_copy" class="q-ml-sm" @click="copyToClipboard(installationPath)" />
              </div>
            </div>
          </div>
        </div>
      </div>
    </q-card-section>
  </q-card>

    <!-- Restart confirmation dialog -->
    <q-dialog v-model="showRestartDialog" persistent>
      <q-card style="min-width: 400px">
        <q-card-section>
          <div class="text-h6">{{ t('restart_watchdog_title') }}</div>
        </q-card-section>

        <q-card-section class="q-pt-none">
          <p class="text-body2">{{ t('restart_watchdog_warning') }}</p>
          <p class="text-weight-medium q-mt-md">{{ t('type_restart_to_confirm') }}</p>
          <q-input
            v-model="confirmText"
            outlined
            dense
            autofocus
            :placeholder="t('type_restart')"
            class="q-mt-sm"
          />
        </q-card-section>

        <q-card-actions align="right" class="q-pt-none">
          <f-btn
            appearance="cancel"
            :label="t('cancel')"
            @click="closeDialog"
          />
          <f-btn
            appearance="negative"
            :label="restartInProgress ? t('restarting') : t('restart')"
            :blocked="confirmText !== 'RESTART' || restartInProgress"
            :loading="restartInProgress"
            @click="executeRestart"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Auto-Update Confirmation Dialog -->
    <q-dialog v-model="showAutoUpdateDialog" persistent>
      <q-card style="min-width: 350px">
        <q-card-section>
          <div class="text-h6">{{ t('auto_update_confirm_title') }}</div>
        </q-card-section>
        <q-card-section class="q-pt-none">
          {{ autoUpdateEnabled ? t('auto_update_disable_warning') : t('auto_update_enable_warning') }}
        </q-card-section>
        <q-card-actions align="right">
          <f-btn
            appearance="cancel"
            :label="t('cancel')"
            @click="showAutoUpdateDialog = false"
          />
          <f-btn
            :appearance="autoUpdateEnabled ? 'negative' : 'positive'"
            :label="autoUpdateEnabled ? t('disable') : t('enable')"
            @click="executeAutoUpdateToggle"
            :loading="autoUpdateInProgress"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>

    <!-- Update confirmation dialog -->
    <q-dialog v-model="showUpdateDialog" persistent>
      <q-card style="min-width: 350px">
        <q-card-section>
          <div class="text-h6">{{ t('update_watchdog_title') }}</div>
        </q-card-section>
        <q-card-section class="q-pt-none">
          <p>{{ t('update_watchdog_warning') }}</p>
          <p class="text-caption text-secondary-adaptive q-mt-sm">
            {{ updateVersionInfo }}
          </p>
        </q-card-section>
        <q-card-actions align="right">
          <f-btn
            appearance="cancel"
            :label="t('cancel')"
            @click="showUpdateDialog = false"
          />
          <f-btn
            appearance="warning"
            :label="t('update')"
            @click="executeUpdate"
            :loading="updateInProgress"
          />
        </q-card-actions>
      </q-card>
    </q-dialog>
  </div>
</template>

<script setup lang="ts">
import { notify } from 'src/components/notifications/notify';
import { ref, computed, onMounted, onUnmounted, watch } from 'vue';
import { useTranslate } from '@tolgee/vue';
import { useFormattedTimeAgo } from 'src/boot/timeago';
import { exportApiService } from 'src/services';
import type { WatchdogStatusResponse } from 'src/services/document/exportApiService';
import FBtn from 'src/single-component/FellowButton.vue';
const t = useTranslate().t;

// State
const status = ref<WatchdogStatusResponse | null>(null);
const loading = ref(true);
const error = ref<string | null>(null);
let pollInterval: number | null = null;

// Restart state
const showRestartDialog = ref(false);
const confirmText = ref('');
const restartInProgress = ref(false);

// Auto-update state
const showAutoUpdateDialog = ref(false);
const autoUpdateInProgress = ref(false);

// Update state
const showUpdateDialog = ref(false);
const updateInProgress = ref(false);

// Computed properties
const isOnline = computed(() => status.value?.online ?? false);
const lastSeen = computed(() => status.value?.last_seen);
const hasPendingCommands = computed(() => status.value?.has_pending_commands ?? false);

const statusIcon = computed(() => isOnline.value ? 'cloud_done' : 'cloud_off');
const statusColor = computed(() => isOnline.value ? 'positive' : 'negative');
const statusLabel = computed(() =>
  isOnline.value ? t.value('status_online') : t.value('status_offline')
);
const statusTextClass = computed(() =>
  isOnline.value ? 'text-positive' : 'text-negative'
);

const formattedLastSeen = computed(() => {
  if (!lastSeen.value) return t.value('never');
  return useFormattedTimeAgo(lastSeen.value);
});

const exactTimestamp = computed(() => {
  if (!lastSeen.value) return '';
  return new Date(lastSeen.value).toLocaleString();
});

// Last restart
const lastRestart = computed(() => status.value?.last_restart);

const formattedLastRestart = computed(() => {
  if (!lastRestart.value) return t.value('never_restarted');
  const date = new Date(lastRestart.value);
  return date.toLocaleString('en-US', {
    month: 'short',
    day: 'numeric',
    year: 'numeric',
    hour: 'numeric',
    minute: '2-digit',
    hour12: true,
  });
});

// Version display logic
const displayVersion = computed(() => {
  if (!status.value) return null;
  if (!status.value.online) return t.value('version_offline');
  if (!status.value.version || status.value.version === '') return t.value('version_unknown');
  return `v${status.value.version}`;
});

const displayInstallDate = computed(() => {
  if (!status.value?.version_first_seen) return null;
  if (!status.value.online) return null;
  try {
    const date = new Date(status.value.version_first_seen);
    return date.toLocaleDateString(undefined, {
      year: 'numeric',
      month: 'short',
      day: 'numeric',
    });
  } catch {
    return null;
  }
});

const autoUpdateEnabled = computed(() => {
  return status.value?.auto_update_enabled ?? null;
});

// System info - bytes formatting helper
const formatBytes = (bytes: number | null | undefined): string => {
  if (!bytes) return t.value('unknown');
  const gb = bytes / (1024 * 1024 * 1024);
  if (gb >= 1) return `${gb.toFixed(1)} GB`;
  const mb = bytes / (1024 * 1024);
  return `${mb.toFixed(0)} MB`;
};

// System info computed properties
const installationPath = computed(() => status.value?.installation_path || null);
const freeRam = computed(() => formatBytes(status.value?.free_ram_bytes));
const freeDisk = computed(() => formatBytes(status.value?.free_disk_bytes));

// Copy helper function
const copyToClipboard = async (text: string | null) => {
  if (!text) return;
  try {
    await navigator.clipboard.writeText(text);
    notify.success(t.value('copied_to_clipboard'));
  } catch (err) {
    console.error('Failed to copy:', err);
  }
};

// Check if update is available
const hasUpdate = computed(() => {
  const installed = status.value?.version;
  const latest = status.value?.latest_version;

  if (!installed || !latest) return false;
  if (installed === '0.0.0') return false; // Unknown installed version

  // Simple semver comparison (works for X.Y.Z format)
  return latest > installed;
});

// Tooltip text showing version comparison
const updateTooltip = computed(() => {
  if (!hasUpdate.value) return '';
  return `v${status.value?.version} -> v${status.value?.latest_version}`;
});

// Update button disabled logic
const isUpdateDisabled = computed(() =>
  !isOnline.value || hasPendingCommands.value || updateInProgress.value
);

const updateDisabledReason = computed(() => {
  if (!isOnline.value) return t.value('watchdog_offline_tooltip');
  if (hasPendingCommands.value) return t.value('command_pending_tooltip');
  if (updateInProgress.value) return t.value('update_in_progress');
  return '';
});

// Version info for dialog (e.g., "v1.2.3 -> v1.3.0")
const updateVersionInfo = computed(() => {
  if (!hasUpdate.value) return '';
  return `v${status.value?.version} -> v${status.value?.latest_version}`;
});

// Restart button disabled logic
const isRestartDisabled = computed(() =>
  !isOnline.value || hasPendingCommands.value || restartInProgress.value
);

const restartDisabledReason = computed(() => {
  if (!isOnline.value) return t.value('watchdog_offline_tooltip');
  if (hasPendingCommands.value) return t.value('command_pending_tooltip');
  if (restartInProgress.value) return t.value('restart_in_progress');
  return '';
});

// API call
const fetchStatus = async () => {
  try {
    const response = await exportApiService.getWatchdogStatus();
    if (response.success !== false) {
      status.value = response;
    }
    error.value = null;
  } catch (err) {
    console.error('[WatchdogStatus] Fetch failed:', err);
    error.value = t.value('error_fetching_status');
    // Don't clear status - keep showing last known state
  } finally {
    loading.value = false;
  }
};

// Dialog management
const closeDialog = () => {
  showRestartDialog.value = false;
  confirmText.value = '';
};

// Watch dialog to reset confirmText when opened
watch(showRestartDialog, (isOpen) => {
  if (isOpen) {
    confirmText.value = '';
  }
});

// Execute restart
const executeRestart = async () => {
  if (confirmText.value !== 'RESTART') return;

  restartInProgress.value = true;

  try {
    const response = await exportApiService.createWatchdogCommand('RESTART');

    if (response.success) {
      notify.success(t.value('watchdog_restart_queued'));
      closeDialog();
      // Trigger immediate status refresh to show pending state
      await fetchStatus();
    } else {
      notify.error(t.value('watchdog_restart_failed'), {
        detail: response.message || t.value('unknown_error'),
        duration: Infinity,
      });
    }
  } catch (err) {
    console.error('[WatchdogStatus] Restart failed:', err);
    notify.error(t.value('watchdog_restart_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
      duration: Infinity,
    });
  } finally {
    restartInProgress.value = false;
  }
};

// Execute auto-update toggle
const executeAutoUpdateToggle = async () => {
  autoUpdateInProgress.value = true;
  const newValue = !autoUpdateEnabled.value;

  try {
    const response = await exportApiService.createWatchdogCommand(
      'SET_AUTO_UPDATE',
      { enabled: newValue },
    );

    if (response.success) {
      notify.success(t.value('auto_update_setting_queued'));
      showAutoUpdateDialog.value = false;
      await fetchStatus();
    } else {
      notify.error(t.value('auto_update_setting_failed'), {
        detail: response.message || t.value('unknown_error'),
        duration: Infinity,
      });
    }
  } catch (err) {
    console.error('[WatchdogStatus] Auto-update toggle failed:', err);
    notify.error(t.value('auto_update_setting_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
      duration: Infinity,
    });
  } finally {
    autoUpdateInProgress.value = false;
  }
};

// Execute update
const executeUpdate = async () => {
  updateInProgress.value = true;

  try {
    const response = await exportApiService.createWatchdogCommand('UPDATE');

    if (response.success) {
      notify.success(t.value('watchdog_update_queued'));
      showUpdateDialog.value = false;
      // Trigger immediate status refresh to show pending state
      await fetchStatus();
    } else {
      notify.error(t.value('watchdog_update_failed'), {
        detail: response.message || t.value('unknown_error'),
        duration: Infinity,
      });
    }
  } catch (err) {
    console.error('[WatchdogStatus] Update failed:', err);
    notify.error(t.value('watchdog_update_failed'), {
      detail: err instanceof Error ? err.message : t.value('unknown_error'),
      duration: Infinity,
    });
  } finally {
    updateInProgress.value = false;
  }
};

// Lifecycle
onMounted(() => {
  fetchStatus();
  pollInterval = window.setInterval(fetchStatus, 5000); // Poll every 5s
});

onUnmounted(() => {
  if (pollInterval) {
    clearInterval(pollInterval);
  }
});
</script>

